-- interview_questions
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('b47d7d72-fa4d-4281-b9d7-5b70b9aaaf93', 'stateless-vs-stateful-widget', 'What is the difference between StatelessWidget and StatefulWidget?', 'Flutter Fundamentals', '["widgets","basics"]', 'Beginner', 'A StatelessWidget is immutable and rebuilds only when its parent rebuilds; a StatefulWidget holds mutable state via a separate State object and can rebuild itself whenever that state changes.', 'A StatelessWidget describes part of the UI that depends only on the configuration passed into it and the BuildContext. Once built, it never changes on its own — it''s recreated wholesale whenever its parent rebuilds it with new data.

A StatefulWidget is split into two classes: the widget itself (immutable, just configuration) and a State object that Flutter keeps alive across rebuilds. Calling setState() inside the State object marks it dirty and schedules a rebuild of just that subtree, without needing the parent to rebuild.', 'dart', 'class Counter extends StatefulWidget {
  const Counter({super.key});

  @override
  State<Counter> createState() => _CounterState();
}

class _CounterState extends State<Counter> {
  int _count = 0;

  void _increment() => setState(() => _count++);

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      onPressed: _increment,
      child: Text(''Count: $_count''),
    );
  }
}', '["Calling setState() after the widget has been disposed (always guard with `mounted` checks in async callbacks).","Putting state in a StatelessWidget by mutating a field directly — it won''t trigger a rebuild."]', '["Explain *why* the split exists: the State object survives widget rebuilds, which is how Flutter preserves things like scroll position and animation controllers."]', '["flutter-widget-lifecycle","avoid-unnecessary-rebuilds"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('eb848e5b-5fe1-4ed2-a639-37d84b6ed6a7', 'what-is-flutter', 'What is Flutter?', 'Flutter Fundamentals', '["basics"]', 'Beginner', 'Flutter is Google''s open-source UI toolkit for building natively compiled apps for mobile, web, and desktop from a single Dart codebase.', 'Flutter renders its own widgets directly to a canvas via the Skia (and newer Impeller) graphics engine, instead of wrapping native platform widgets. This means a Flutter app looks and behaves identically across platforms, and isn''t limited by the native widget set. The trade-off is that Flutter ships its own rendering engine with the app, which makes apps slightly larger but gives full control over every pixel and consistent 60/120fps performance.

Flutter apps are written in Dart, compiled ahead-of-time (AOT) to native ARM/x64 machine code for release builds, which is why performance is close to native. During development, Dart''s just-in-time (JIT) compiler powers hot reload, letting you see UI changes in under a second without restarting the app.', NULL, NULL, '["Saying Flutter \"wraps native widgets\" — it doesn''t; it paints everything itself.","Confusing Flutter (the UI toolkit) with Dart (the language) as if they''re the same thing."]', '["Mention the rendering engine (Skia/Impeller) — it shows you understand why Flutter looks consistent across platforms.","Be ready to contrast this with React Native, which bridges to native widgets."]', '["stateless-vs-stateful-widget","flutter-architecture-overview"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:47:55.001497+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('73cee155-ab48-4d0b-9e8b-d938c80be31e', 'flutter-widget-lifecycle', 'Explain the widget lifecycle in Flutter.', 'Flutter Fundamentals', '["widgets","lifecycle"]', 'Intermediate', 'A StatefulWidget''s State goes through createState → initState → didChangeDependencies → build (repeated) → didUpdateWidget (on parent rebuild) → deactivate → dispose.', 'createState() is called once when the framework first creates the State object. initState() runs once, right after, and is where you set up controllers, subscriptions, or one-time initialization — note that BuildContext and inherited widgets aren''t fully available yet, so don''t use them here for anything that depends on InheritedWidget data.

didChangeDependencies() runs after initState() and again whenever an InheritedWidget the State depends on changes. build() is called every time the framework needs to re-render — it can run many times and must be fast and side-effect-free. If the parent rebuilds with a new widget instance for the same State, didUpdateWidget(oldWidget) runs so you can react to changed configuration. Finally, deactivate() runs when the State is removed from the tree (it may be reinserted elsewhere, e.g. with GlobalKey), and dispose() runs when it''s permanently removed — this is where you cancel subscriptions and dispose controllers.', NULL, NULL, '["Doing expensive work inside build() instead of initState() or a memoized value.","Forgetting to dispose() AnimationControllers, StreamSubscriptions, or TextEditingControllers, causing memory leaks."]', '["Naming the exact order (initState → didChangeDependencies → build → didUpdateWidget → dispose) signals real hands-on experience, not just memorized definitions."]', '["stateless-vs-stateful-widget","flutter-memory-management"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('c62b67bf-2c53-4773-85fc-a8c3c7a5a371', 'dart-null-safety', 'What is null safety in Dart?', 'Dart Questions', '["null-safety"]', 'Beginner', 'Sound null safety means the compiler distinguishes nullable (`String?`) from non-nullable (`String`) types and guarantees, at compile time, that a non-nullable variable can never hold null.', 'Before null safety, any variable could be null, which made NullPointerException-style crashes ("Null check operator used on a null value" in Dart) one of the most common runtime errors. With sound null safety, every type is non-nullable by default; you opt into nullability explicitly with a `?` suffix.

The compiler then enforces this everywhere: you must either check for null, provide a default with `??`, or assert non-null with `!` (the null assertion operator) before using a nullable value where a non-nullable one is expected. Because the guarantee is sound (not just a lint), the Dart compiler can also use this information to generate more optimized code.', 'dart', 'String? maybeName;          // nullable
String name = maybeName ?? ''Guest'';   // default with ??
String forced = maybeName!;           // asserts non-null (throws if null)

void greet(String name) => print(''Hello, $name'');
// greet(maybeName); // compile error: String? isn''t String', '["Overusing the `!` null-assertion operator to silence the compiler instead of actually handling the null case — this just moves the crash to runtime.","Marking everything nullable \"to be safe\" instead of modeling which fields are genuinely optional."]', '["Distinguish sound null safety from a linter warning — Dart''s guarantee is enforced by the type system itself, including across libraries."]', '["dart-async-await","dart-data-class-generator"]', '[]', '["json-to-dart","dart-data-class-generator"]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('fbd2dffd-68db-4c12-9250-5630098695f4', 'future-vs-stream', 'What is the difference between Future and Stream in Dart?', 'Dart Questions', '["futures","streams"]', 'Intermediate', 'A Future represents a single asynchronous value that completes once; a Stream represents a sequence of asynchronous values delivered over time, and can emit zero, one, or many events.', 'A Future is like a promise of one value (or error) at some point in the future — a network request that returns one JSON response is a Future. You consume it with `await` or `.then()`.

A Stream is for ongoing data — user input events, WebSocket messages, or a Firestore document that keeps updating. You consume it with `await for` inside an async function, or by calling `.listen()` to register a callback for each event. Streams can be single-subscription (only one listener ever, used for things like file reads) or broadcast (multiple simultaneous listeners, used for things like a click-event bus).', 'dart', 'Future<String> fetchUser() async {
  final response = await http.get(Uri.parse(''/api/user''));
  return response.body; // resolves once
}

Stream<int> countdown() async* {
  for (int i = 3; i > 0; i--) {
    await Future.delayed(const Duration(seconds: 1));
    yield i; // emits multiple times
  }
}', '["Trying to `await` a Stream directly instead of using `await for` or `.listen()`.","Forgetting to cancel a StreamSubscription in `dispose()`, leaking the listener."]', '[]', '["dart-async-await","flutter-memory-management"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('f76d1e22-f39b-40b2-9c0a-d633aae6be85', 'dart-async-await', 'How does async/await work in Dart?', 'Dart Questions', '["async-await"]', 'Beginner', '`async` marks a function as returning a Future and lets you use `await` inside it; `await` pauses execution of that function (without blocking the thread) until the awaited Future completes.', 'Dart is single-threaded for your app code (it uses an event loop, not OS threads, for concurrency). When you `await` a Future, Dart doesn''t block the thread — it suspends the current async function and lets the event loop keep processing other work (like UI rendering) until the awaited value is ready, then resumes exactly where it left off.

An `async` function always returns a Future, even if you don''t explicitly wrap the return value — `Future<int> getCount() async { return 5; }` returns a `Future<int>` that completes with 5. Errors thrown inside an async function become a failed Future, which you catch with try/catch around the `await`, same as synchronous code.', 'dart', 'Future<void> loadProfile() async {
  try {
    final user = await fetchUser();
    print(user);
  } catch (e) {
    print(''Failed to load: $e'');
  }
}', '["Marking a function `async` but forgetting to `await` a Future inside it — the function returns before the work finishes.","Thinking `await` blocks the UI thread — it doesn''t; it yields control back to the event loop."]', '[]', '["future-vs-stream","dart-null-safety"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('1838ac0b-a90c-42bc-86d2-c876afcd8bee', 'dart-extensions', 'What are extension methods in Dart?', 'Dart Questions', '["extensions"]', 'Intermediate', 'Extension methods let you add new functionality to an existing type — including types you don''t own, like String or int — without modifying its source or subclassing it.', 'Normally, to add a method to a class you either edit its source or create a subclass. Extensions sidestep both: you declare `extension <Name> on <Type> { ... }` and any method or getter inside becomes callable on instances of that type, as if it were built in.

Extensions are resolved statically at compile time based on the declared type of the variable, not its runtime type, and they only apply where the extension is imported and visible — there''s no global mutation of the type happening.', 'dart', 'extension StringCasingExtension on String {
  String capitalize() =>
      isEmpty ? this : ''${this[0].toUpperCase()}${substring(1)}'';
}

void main() {
  print(''flutter''.capitalize()); // "Flutter"
}', '["Assuming extension methods are dynamically dispatched like normal instance methods — they''re resolved by static type.","Defining two extensions with conflicting method names on the same type and being surprised by ambiguity errors."]', '[]', '["dart-mixins"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('acce1be7-37e0-460e-bded-8a752041dc43', 'dart-mixins', 'What are mixins in Dart and when would you use one?', 'Dart Questions', '["mixins"]', 'Intermediate', 'A mixin lets a class reuse a chunk of behavior from multiple sources without using multiple inheritance — you declare it with `mixin` and apply it with `with`.', 'Dart classes can only extend one superclass, but a class can mix in several mixins, each contributing methods and fields. This is useful for cross-cutting behavior that doesn''t fit a single inheritance hierarchy — for example, a `Validatable` mixin that adds validation logic to several unrelated form-field classes.

You can restrict which classes are allowed to use a mixin with the `on` clause (e.g. `mixin Flying on Animal`), which lets the mixin call methods it assumes the host class provides. Unlike a regular class, a mixin generally can''t have its own constructor.', 'dart', 'mixin Loggable {
  void log(String message) => print(''[LOG] $message'');
}

class ApiClient with Loggable {
  void fetch() {
    log(''Fetching data...'');
  }
}', '["Confusing mixins with abstract classes — a mixin can''t be instantiated directly with `new`/a constructor call.","Overusing mixins for things that would be clearer as plain composition (passing in a dependency instead of mixing in behavior)."]', '[]', '["dart-extensions"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('3f2762a6-eee5-4e43-b0cb-41d1cf29978e', 'what-is-provider', 'What is the Provider package and how does it work?', 'State Management', '["provider"]', 'Beginner', 'Provider is a wrapper around Flutter''s InheritedWidget that makes it easy to expose and listen to a piece of state from anywhere below it in the widget tree, and to rebuild only the widgets that actually depend on it.', 'You wrap part of your widget tree in a `ChangeNotifierProvider` (or similar provider type), supplying a `ChangeNotifier` subclass that holds your state and calls `notifyListeners()` whenever it changes. Descendant widgets read that state with `context.watch<T>()` (rebuilds on change), `context.read<T>()` (reads once, doesn''t rebuild — typically used inside callbacks), or the `Consumer<T>` widget for fine-grained rebuild scoping.

Provider''s main value over raw InheritedWidget is dependency lookup and disposal handled for you, plus a clear, idiomatic API that the Flutter team itself recommended for years as the default state management approach for small-to-medium apps.', NULL, NULL, '["Calling `context.watch<T>()` inside a callback (like `onPressed`) instead of `context.read<T>()` — watch should only be used during build.","Putting business logic directly in widgets instead of in the ChangeNotifier."]', '[]', '["riverpod-vs-provider","bloc-pattern-explained"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('7cd6b936-63c0-4a6a-8182-980b9d65d723', 'riverpod-vs-provider', 'How does Riverpod differ from Provider?', 'State Management', '["riverpod","provider"]', 'Intermediate', 'Riverpod is a redesign by the same author as Provider that removes the dependency on BuildContext and the widget tree, catching errors at compile time instead of runtime, and making providers globally accessible and easily testable.', 'Provider relies on InheritedWidget, which means lookups can fail at runtime if you call `context.watch<T>()` above the provider in the tree, or if the type is wrong — these show up as runtime exceptions. Riverpod declares providers as plain top-level (or class) objects, completely decoupled from BuildContext, so the compiler can catch a missing or mistyped provider before you even run the app.

Riverpod also makes providers easy to override for testing (e.g. swapping a real repository provider for a mock one in a test''s `ProviderScope`), supports automatic disposal of state that''s no longer being listened to (`autoDispose`), and has first-class support for async state via `FutureProvider`/`StreamProvider` with built-in loading/error/data states.', NULL, NULL, '["Assuming Riverpod is just \"Provider 2.0\" with the same mental model — its decoupling from BuildContext changes how you structure dependencies.","Not using `autoDispose` where appropriate, leading to providers that never get cleaned up."]', '["Mention that Riverpod is a separate package (not part of Flutter SDK), unlike some assume."]', '["what-is-provider","bloc-pattern-explained"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('a4c37eb1-9db4-4e93-a88e-cd6d41ed361d', 'bloc-pattern-explained', 'What is the BLoC pattern in Flutter?', 'State Management', '["bloc"]', 'Intermediate', 'BLoC (Business Logic Component) separates UI from business logic by having the UI dispatch Events into a Bloc, which processes them and emits new States that the UI rebuilds from — all communication happens through a strict, unidirectional stream of Events and States.', 'A widget never mutates state directly. Instead, it sends an Event (e.g. `IncrementPressed()`) into a Bloc using `context.read<CounterBloc>().add(IncrementPressed())`. The Bloc''s internal logic maps that event to a new State (e.g. `CounterState(count: count + 1)`) and emits it. The UI listens via `BlocBuilder` (rebuild on state changes) or `BlocListener` (side effects like navigation/snackbars without rebuilding), so the data flow is always Event → Bloc → State → UI, never the reverse.

This strict separation makes business logic fully testable without any widget tree at all — you can unit test a Bloc by feeding it events and asserting on the emitted states, with no Flutter dependency in the test.', NULL, NULL, '["Putting Flutter-specific code (like `BuildContext`) inside a Bloc — it should be pure Dart, completely UI-agnostic.","Confusing `BlocBuilder` (for rebuilding UI) with `BlocListener` (for one-off side effects) and using the wrong one."]', '[]', '["riverpod-vs-provider","clean-architecture-flutter"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('9711d4a8-0012-4e8e-92b0-9bd08a1ca3c9', 'getx-state-management', 'What is GetX and what does it offer for state management?', 'State Management', '["getx"]', 'Beginner', 'GetX is an all-in-one Flutter package combining reactive state management, dependency injection, and route navigation, designed to minimize boilerplate with a small, simple API.', 'For state, GetX offers two main styles: wrapping a value in `.obs` to make it observable and rebuilding with `Obx(() => Text(''${counter.value}''))`, or using `GetBuilder` for a more manual, controller-based update model. For dependency injection, `Get.put()`/`Get.find()` register and retrieve controllers without needing a wrapping widget like Provider requires. For navigation, `Get.to()` lets you push routes without a BuildContext at all.

The trade-off developers debate is that GetX''s convenience (especially context-free navigation and DI) comes at the cost of being a large, opinionated, all-in-one dependency rather than composable single-purpose packages — some teams prefer combining a focused state package (Riverpod/Bloc) with a separate router (go_router) instead.', NULL, NULL, '["Treating GetX''s context-free APIs as universally good practice without understanding the testability/coupling trade-offs."]', '[]', '["what-is-provider","riverpod-vs-provider"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('5713d0d1-a164-4175-8fe3-578280f65392', 'const-widgets-flutter', 'Why should you use const widgets in Flutter?', 'Flutter Performance', '["const"]', 'Beginner', 'A `const` widget is created once at compile time and reused across rebuilds — Flutter can skip rebuilding it entirely because it knows the instance can never change.', 'When a widget''s constructor and all its arguments are compile-time constants, marking it `const` tells Dart to create exactly one instance, shared everywhere it''s used. During a rebuild, Flutter compares the new widget instance to the old one; if they''re `==` (which `const` instances are, by identity), it skips rebuilding that subtree entirely instead of diffing it.

This matters most for static decoration — icons, dividers, fixed-text labels — nested deep inside frequently-rebuilding parents. It costs nothing to add and the Dart analyzer (`prefer_const_constructors` lint) will even suggest it for you.', 'dart', '// Rebuilt fresh every time the parent rebuilds:
Icon(Icons.star, color: Colors.amber)

// Created once, reused forever:
const Icon(Icons.star, color: Colors.amber)', '["Not marking a widget `const` just because it \"looks dynamic\" when its actual arguments are all compile-time constants.","Wrapping a `const`-eligible subtree in a non-const parent and assuming the optimization still applies — the analyzer will flag if it doesn''t propagate."]', '[]', '["avoid-unnecessary-rebuilds","flutter-architecture-overview"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('570699ed-deb5-44b0-9df1-b40f812601be', 'avoid-unnecessary-rebuilds', 'How do you avoid unnecessary widget rebuilds in Flutter?', 'Flutter Performance', '["rebuilds"]', 'Intermediate', 'Scope state narrowly (so only the widgets that depend on it rebuild), use `const` constructors wherever possible, and split large build methods into smaller widgets so a change in one part doesn''t force the whole tree to re-render.', 'The single biggest cause of unnecessary rebuilds is calling `setState()` (or having a `Provider`/`Riverpod` watcher) high up in a large widget tree, which forces everything below it to rebuild even if only a small piece actually changed visually. The fix is to push state down: extract the part of the UI that actually changes into its own small widget, and keep state management scoped to just that subtree.

For Provider/Riverpod specifically, prefer `Selector`/`Consumer` (or `ref.watch(provider.select(...))` in Riverpod) to listen to only the specific field you need, rather than the whole object. Also use `const` constructors aggressively, and avoid creating new closures or objects inline inside `build()` (e.g. a new `BoxDecoration` every build) since that defeats Flutter''s ability to detect "nothing changed."', NULL, NULL, '["Wrapping the entire `Scaffold` in a `Consumer`/`Obx` instead of just the small widget that needs the data.","Creating new callback closures or styling objects inline on every build instead of hoisting them out."]', '[]', '["const-widgets-flutter","listview-builder-optimization"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('813b05c1-eb3c-443a-ac2e-02f55544f76b', 'listview-builder-optimization', 'How do you optimize long lists in Flutter?', 'Flutter Performance', '["listview"]', 'Intermediate', 'Use `ListView.builder` (or `SliverList`) instead of building all items eagerly, always provide `key`s for items that can reorder, and avoid expensive work inside the `itemBuilder`.', '`ListView(children: [...])` builds every item immediately, even ones far off-screen — fine for a handful of items, disastrous for hundreds. `ListView.builder` instead lazily builds only the items that are visible (plus a small cache window), calling your `itemBuilder` on demand as the user scrolls.

Beyond that: give list items stable `Key`s (e.g. `ValueKey(item.id)`) so Flutter can correctly match elements when the list reorders, instead of rebuilding everything from scratch. Avoid doing image decoding, JSON parsing, or other expensive work directly inside `itemBuilder` — precompute it before passing data into the list. For extremely long or complex lists, consider `ListView.separated` for dividers without manual index math, or slivers for mixed scrollable content.', 'dart', 'ListView.builder(
  itemCount: items.length,
  itemBuilder: (context, index) {
    final item = items[index];
    return ListTile(
      key: ValueKey(item.id),
      title: Text(item.title),
    );
  },
)', '["Using `ListView(children: items.map(...).toList())` for a long or unbounded list.","Missing `key`s on reorderable list items, causing visual glitches or wrong-item animations."]', '[]', '["avoid-unnecessary-rebuilds","flutter-memory-management"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('8dd0a192-8152-486b-adc7-ea38cd1f179e', 'flutter-memory-management', 'How does Flutter manage memory, and how do you avoid leaks?', 'Flutter Performance', '["memory"]', 'Advanced', 'Dart uses automatic garbage collection, so you don''t free memory manually — leaks in Flutter almost always come from long-lived objects (controllers, streams, listeners) holding references that prevent disposed widgets'' resources from being collected.', 'The Dart VM''s generational garbage collector reclaims objects with no remaining references, so typical "manual memory management" bugs (like double-free) don''t apply. What does cause real leaks in Flutter apps is forgetting to release long-lived resources tied to a widget''s lifetime: an `AnimationController`, `TextEditingController`, `ScrollController`, or `StreamSubscription` started in `initState()` but never released in `dispose()` keeps running (and keeps its callbacks alive) even after the widget is gone.

A second common source is global/static state (singletons, global event buses) holding a reference to a callback or object tied to a specific screen — the screen is popped, but the global reference keeps it (and everything it references) alive. Use Flutter DevTools'' memory view to take heap snapshots and look for unexpectedly retained widget/controller instances after navigating away.', NULL, NULL, '["Subscribing to a Stream or animation in `initState()` without a matching `cancel()`/`dispose()`.","Registering a callback on a global singleton from a screen, then never unregistering it when the screen closes."]', '["Mention Flutter DevTools'' memory snapshot/diff tooling specifically — it shows you''ve actually debugged a leak, not just read about the concept."]', '["flutter-widget-lifecycle","dart-isolates"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('03c85aa8-4a0d-4687-a4d2-6769e2b5e983', 'firebase-auth-flutter', 'How do you implement Firebase Authentication in Flutter?', 'Firebase Integration', '["authentication"]', 'Beginner', 'Add the `firebase_auth` package, initialize Firebase in `main()`, then use `FirebaseAuth.instance` to sign users in (email/password, Google, etc.) and listen to `authStateChanges()` to react to login/logout across the app.', 'After running `flutterfire configure` (which wires up your platform-specific Firebase config files) and calling `Firebase.initializeApp()` before `runApp()`, authentication itself is mostly calling methods on `FirebaseAuth.instance`: `createUserWithEmailAndPassword()`, `signInWithEmailAndPassword()`, or a provider-specific sign-in (e.g. Google Sign-In, which gets an OAuth credential and passes it to `signInWithCredential()`).

The key architectural piece is `FirebaseAuth.instance.authStateChanges()`, a Stream that emits the current `User?` (null when signed out) immediately and on every login/logout. Wrapping your app''s root in a `StreamBuilder` on this stream is the standard way to route between a login screen and the main app reactively, without manually tracking auth state yourself.', 'dart', 'StreamBuilder<User?>(
  stream: FirebaseAuth.instance.authStateChanges(),
  builder: (context, snapshot) {
    if (snapshot.connectionState == ConnectionState.waiting) {
      return const SplashScreen();
    }
    return snapshot.hasData ? const HomeScreen() : const LoginScreen();
  },
)', '["Calling `Firebase.initializeApp()` after `runApp()` instead of before, causing a race condition on startup.","Manually polling `FirebaseAuth.instance.currentUser` instead of listening to `authStateChanges()`."]', '[]', '["firestore-vs-realtime-database","fcm-push-notifications"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('62d534b6-f284-46f2-9959-5738762edc8c', 'firestore-vs-realtime-database', 'What''s the difference between Firestore and the Realtime Database?', 'Firebase Integration', '["firestore"]', 'Intermediate', 'Firestore is a newer, document/collection-based database with richer querying, automatic multi-region scaling, and better offline support; the Realtime Database is a simpler single JSON tree, cheaper for very high-frequency small writes but with weaker querying.', 'Firestore organizes data into documents (JSON-like objects) grouped into collections, and supports compound queries, indexing, and pagination natively. It scales horizontally across regions automatically and its offline persistence layer is more robust — queries work offline and sync seamlessly when reconnected.

The Realtime Database stores everything as one large JSON tree. It''s historically been favored for use cases needing extremely low-latency, high-frequency updates (like live cursor positions or presence systems) because its WebSocket-based sync can be marginally faster for tiny, frequent writes, and its pricing model (bandwidth-based) can be cheaper at that specific workload shape. For most new apps, Google now recommends Firestore by default unless you have that specific high-frequency-small-write profile.', NULL, NULL, '["Assuming Realtime Database is deprecated — it isn''t, it''s just recommended for narrower use cases now.","Trying to run Firestore-style compound queries against the Realtime Database''s flatter query model."]', '[]', '["firebase-auth-flutter","firebase-remote-config"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('dc9ae852-ea8d-4b3a-b551-f3a58a7c4060', 'fcm-push-notifications', 'How do push notifications work with Firebase Cloud Messaging in Flutter?', 'Firebase Integration', '["push-notifications"]', 'Intermediate', 'The app registers with FCM to get a unique device token, your backend (or Firebase console) sends a message to that token via the FCM API, and the `firebase_messaging` package delivers it to the app in foreground, background, or terminated states via different handlers.', 'Each app install gets a device token from `FirebaseMessaging.instance.getToken()`, which you send to your backend so it knows where to deliver messages for that user. When a message arrives, how it''s handled depends on app state: in the foreground, `FirebaseMessaging.onMessage` fires and you typically show your own in-app notification UI (FCM doesn''t auto-display foreground notifications). In the background or terminated, the OS shows the system notification automatically for "notification" payloads, and tapping it triggers `FirebaseMessaging.onMessageOpenedApp` (from background) or a check on `getInitialMessage()` (from terminated) so you can navigate to the right screen.

On iOS specifically, you also need to request notification permission explicitly (`requestPermission()`) and configure APNs certificates/keys in the Firebase console — FCM relies on Apple''s push service under the hood for iOS delivery.', NULL, NULL, '["Forgetting that foreground messages don''t show a system notification automatically — you must build that UI yourself.","Not registering a top-level (non-class) background message handler, which iOS/Android background isolates require."]', '[]', '["firebase-auth-flutter"]', '["firebase-push-notifications-flutter"]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('b31f015e-a6b1-4105-ad6f-e7cf64dca8b9', 'firebase-remote-config', 'What is Firebase Remote Config used for?', 'Firebase Integration', '["remote-config"]', 'Advanced', 'Remote Config lets you change app behavior and appearance — feature flags, A/B test variants, default values — without shipping a new app release, by fetching key/value parameters from the Firebase backend at runtime.', 'You define parameters (and optional conditions, like "users on Android" or "in experiment group B") in the Firebase console, fetch them in-app via `FirebaseRemoteConfig.instance.fetchAndActivate()`, and read values with typed getters (`getBool`, `getString`, etc.) that fall back to in-app defaults if the fetch hasn''t completed yet — so the app always has a sane value even offline or on first launch.

Common uses: gradually rolling out a feature to a percentage of users (a feature flag), running A/B tests by tying parameter values to experiment groups, or changing copy/pricing without an app store release. It pairs naturally with Firebase Analytics and A/B Testing for measuring the impact of different configurations.', NULL, NULL, '["Treating Remote Config as a real-time push mechanism — it''s pull-based; you choose when to fetch (e.g. on app start), it doesn''t push changes instantly.","Not setting in-app default values, leaving the app in an undefined state before the first successful fetch."]', '[]', '["firestore-vs-realtime-database"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('351e9fe4-740e-4a82-9341-7003b7930e6e', 'clean-architecture-flutter', 'What is Clean Architecture and how does it apply to Flutter?', 'Architecture', '["clean-architecture"]', 'Intermediate', 'Clean Architecture separates an app into independent layers — typically presentation, domain, and data — where inner layers (business logic) never depend on outer layers (UI, frameworks, databases), so business rules can be tested and reused independently of Flutter itself.', 'In a typical Flutter implementation: the presentation layer holds widgets and state management (Bloc/Riverpod/Provider), the domain layer holds pure-Dart entities and use cases (business rules with zero Flutter or package imports), and the data layer holds repositories and data sources (API clients, local databases) that implement interfaces defined in the domain layer.

The dependency rule flows inward: presentation depends on domain, data depends on domain, but domain depends on nothing Flutter-specific. This is enforced via the Dependency Inversion Principle — the domain layer defines a `UserRepository` interface (abstract class), and the data layer provides the concrete implementation, which gets injected at the outer edges (often via Provider/Riverpod or a DI container like `get_it`). The payoff is that you can unit test use cases with zero widgets, mock the repository easily, and swap a REST data source for GraphQL without touching business logic.', NULL, NULL, '["Over-engineering tiny apps with the full three-layer structure when a simpler approach would do — Clean Architecture''s value shows up as the app and team grow.","Letting domain-layer code import Flutter packages (like `material.dart`), which breaks the whole point of the separation."]', '["Be ready to explain the Dependency Inversion Principle specifically — it''s the mechanism that makes the layering actually work, not just a folder structure."]', '["repository-pattern-flutter","dependency-injection-flutter"]', '["flutter-clean-architecture-2026"]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('bebab567-ce4b-477f-bb5e-9323c15591b7', 'repository-pattern-flutter', 'What is the Repository pattern?', 'Architecture', '["repository-pattern"]', 'Intermediate', 'The Repository pattern puts a single abstraction in front of however data is actually fetched or stored — network, local cache, database — so the rest of the app talks to one consistent interface and doesn''t care where the data comes from.', 'Instead of widgets or use cases calling an HTTP client directly, they depend on a repository interface like `abstract class UserRepository { Future<User> getUser(String id); }`. The concrete implementation decides internally whether to hit the network, read a local cache, or merge both (e.g. return cached data immediately, then refresh from network) — that decision is invisible to everything calling the repository.

This gives you two big wins: you can swap the underlying data source (REST today, GraphQL tomorrow, or add an offline cache) without touching any calling code, and you can substitute a fake/mock repository in tests so business logic tests never make real network calls.', 'dart', 'abstract class UserRepository {
  Future<User> getUser(String id);
}

class UserRepositoryImpl implements UserRepository {
  UserRepositoryImpl(this._api, this._cache);
  final ApiClient _api;
  final LocalCache _cache;

  @override
  Future<User> getUser(String id) async {
    final cached = _cache.getUser(id);
    if (cached != null) return cached;
    final user = await _api.fetchUser(id);
    _cache.saveUser(user);
    return user;
  }
}', '["Creating a repository that just forwards every call to one data source with no added logic — at that point it''s not adding value over calling the data source directly.","Leaking data-source-specific types (like an HTTP response model) out through the repository interface instead of returning domain entities."]', '[]', '["clean-architecture-flutter","dependency-injection-flutter"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('c2d2f9e4-bbf3-4e4e-b0de-5446d509ad01', 'dependency-injection-flutter', 'What is Dependency Injection and how is it used in Flutter?', 'Architecture', '["dependency-injection"]', 'Advanced', 'Dependency Injection means a class receives its dependencies from the outside (via constructor or a container) instead of creating them itself, which decouples classes from concrete implementations and makes them easy to test with substitutes.', 'Without DI, a class might do `final repo = UserRepositoryImpl();` directly inside itself — now it''s permanently coupled to that exact implementation and can''t be tested without hitting a real API. With DI, the class instead declares `UserRepository repo` as a constructor parameter, and something else (a parent widget, a DI container, or a provider) decides which concrete implementation to hand it.

In Flutter, this is commonly done via Provider/Riverpod (providers are themselves a form of DI — they supply object instances to the widget tree) or a dedicated service locator like `get_it`, where you register implementations once (often at app startup) and retrieve them anywhere with `GetIt.instance<UserRepository>()`. The key benefit in tests: you register a fake implementation in the container before the test runs, and every class that depends on that interface transparently gets the fake instead of the real thing.', NULL, NULL, '["Confusing a service locator (`get_it`) with true dependency injection — a service locator still has classes reaching out to grab their dependencies, just from a registry instead of constructing them; constructor injection is the stricter form.","Registering dependencies in a way that creates circular dependencies between services."]', '[]', '["clean-architecture-flutter","repository-pattern-flutter"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('23b122a0-8c37-4f75-abfb-0d9f5c58fd83', 'dart-isolates', 'What are isolates in Dart and when do you need them?', 'Advanced Flutter', '["isolates"]', 'Advanced', 'An isolate is Dart''s unit of concurrency — a separate memory heap and event loop running independently, with no shared mutable state — used to run CPU-heavy work in parallel without blocking the UI thread.', 'Dart''s main isolate runs your UI and event loop; `await`ing a network call doesn''t block it because I/O is non-blocking, but genuinely CPU-bound work (parsing a huge JSON file, image processing, heavy computation) does block it, causing dropped frames and jank, because there''s no thread for it to yield to.

Isolates solve this by running that work on a separate isolate with its own memory — communication happens only via message-passing (ports), never shared memory, which is why Dart doesn''t need locks/mutexes for isolate-to-isolate communication. The easy way to spin one up for a single task is `compute()` from Flutter, which runs a top-level function on a new isolate and returns its result as a Future. For longer-lived background work, you manage an `Isolate` and `ReceivePort` directly.', 'dart', '// Runs on a separate isolate, doesn''t block the UI thread
final result = await compute(parseHeavyJson, rawJsonString);

List<Item> parseHeavyJson(String raw) {
  final data = jsonDecode(raw) as List;
  return data.map((e) => Item.fromJson(e)).toList();
}', '["Using isolates for I/O-bound work (network calls) that already doesn''t block the main isolate — isolates only help with CPU-bound work.","Passing non-message-safe objects (like a class holding a `BuildContext`) across the isolate boundary."]', '["Mention `compute()` by name — it''s the practical, most-used entry point and shows real usage, not just textbook knowledge."]', '["flutter-memory-management","platform-channels-flutter"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('2ef3be50-f4f4-4905-a4b8-fad86a38fac0', 'flutter-animations-overview', 'What are the main ways to build animations in Flutter?', 'Advanced Flutter', '["animations"]', 'Intermediate', 'Implicit animations (the `Animated*` widgets, like `AnimatedContainer`) animate a property change automatically with minimal code; explicit animations give full control via an `AnimationController` and `Tween`, for anything beyond a simple property tween.', 'Implicit animations are the fast path: wrap a value in `AnimatedContainer`, `AnimatedOpacity`, etc., change the target value (e.g. a new `color` or `width`), and Flutter animates the transition automatically over the given `duration` — no controller needed. This covers most simple "animate this property when it changes" cases.

Explicit animations give you precise control: you create an `AnimationController` (which drives a value over time, typically 0 to 1), wrap it in a `Tween` to map that range onto the actual values you want (e.g. a color or a rotation), and rebuild via `AnimatedBuilder` whenever the controller ticks. This is necessary for coordinating multiple animations, repeating/reversing animations, responding to gestures mid-animation, or anything an implicit widget doesn''t expose a parameter for. There''s also the newer declarative animation API for Flutter''s animated transitions between routes/widgets, but controller-based explicit animation remains the foundation for complex custom motion.', 'dart', 'class _FadeInState extends State<FadeIn> with SingleTickerProviderStateMixin {
  late final _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 400),
  )..forward();
  late final _opacity = CurvedAnimation(parent: _controller, curve: Curves.easeIn);

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) =>
      FadeTransition(opacity: _opacity, child: widget.child);
}', '["Forgetting to `dispose()` an `AnimationController`, leaking the ticker.","Reaching for explicit `AnimationController` setup when an `Animated*` implicit widget would do the job in two lines."]', '[]', '["custom-painter-flutter","flutter-memory-management"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('cd52293d-ba47-49a3-b435-59fe27eb2084', 'custom-painter-flutter', 'What is CustomPainter used for?', 'Advanced Flutter', '["custom-painter"]', 'Advanced', 'CustomPainter lets you draw directly onto a canvas with low-level drawing primitives (paths, arcs, text, gradients) for visuals that no combination of standard widgets can produce — charts, custom shapes, signature pads.', 'You subclass `CustomPainter`, implement `paint(Canvas canvas, Size size)` with direct drawing calls (`canvas.drawPath`, `canvas.drawCircle`, `canvas.drawLine`, etc.), and implement `shouldRepaint(oldDelegate)` to tell Flutter whether it needs to repaint when something changes — returning `false` when nothing relevant changed avoids wasted repaints. You attach it to the tree via a `CustomPaint` widget, optionally giving it a `size` and a `child` to paint over/under.

This is the right tool when you need pixel-level control that widgets can''t express — a custom progress ring, a chart, a hand-drawn signature capture, or a complex clipped/gradient shape. For most "slightly custom" visuals, reach for `ClipPath`, `ShaderMask`, or `DecoratedBox` first; CustomPainter is for when those genuinely aren''t enough.', 'dart', 'class RingPainter extends CustomPainter {
  RingPainter(this.progress);
  final double progress; // 0.0 - 1.0

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.blue
      ..style = PaintingStyle.stroke
      ..strokeWidth = 8;
    final rect = Rect.fromLTWH(0, 0, size.width, size.height);
    canvas.drawArc(rect, -1.57, progress * 6.28, false, paint);
  }

  @override
  bool shouldRepaint(RingPainter old) => old.progress != progress;
}', '["Always returning `true` from `shouldRepaint`, forcing a repaint on every frame regardless of whether anything changed.","Doing expensive computation inside `paint()` instead of precomputing it before passing data to the painter."]', '[]', '["flutter-animations-overview"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('d3408508-0fbf-446d-99e2-ef4dbb30b0c6', 'platform-channels-flutter', 'What are platform channels and why are they needed?', 'Advanced Flutter', '["platform-channels"]', 'Advanced', 'Platform channels are Flutter''s message-passing bridge to native platform code (Kotlin/Java on Android, Swift/Objective-C on iOS) — used whenever you need a platform API or native SDK that has no Dart equivalent.', 'Flutter''s Dart code doesn''t run inside the native platform''s runtime, so it can''t call native APIs directly. A `MethodChannel` lets Dart invoke a named method with arguments and asynchronously receive a result, while the native side registers a handler for that channel name and method. Communication is serialized through a standard message codec (supporting primitives, lists, maps), so both sides need to agree on the channel name and method names as a contract.

This is needed for things with no existing Flutter package: a proprietary native SDK, a platform-specific API not yet wrapped by a plugin, or custom native UI embedding (via `PlatformView`). In practice, most apps never write raw platform channel code directly — they consume a plugin package that already wraps this for a specific capability (camera, Bluetooth, etc.) — but understanding the mechanism matters once you need a capability no plugin covers yet, or you''re building a plugin yourself.', 'dart', 'const channel = MethodChannel(''com.bidev.app/battery'');

Future<int> getBatteryLevel() async {
  final level = await channel.invokeMethod<int>(''getBatteryLevel'');
  return level ?? -1;
}', '["Assuming platform channel calls are synchronous — they''re always asynchronous (a Future on the Dart side).","Mismatching the channel name or method name string between Dart and native code, causing a silent `MissingPluginException`."]', '[]', '["dart-isolates"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T13:40:25.965992+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('6b876c16-9e39-480f-a3c2-cb54630adf88', 'flutter-architecture-overview', 'Describe Flutter''s architecture — how does a widget end up as pixels on screen?', 'Flutter Fundamentals', '["rendering"]', 'Intermediate', 'Flutter has three parallel trees Widget, Element, and RenderObject where widgets are immutable configuration, elements are the mutable instances that manage the tree, and render objects handle layout, painting, and hit-testing.', 'The Widget tree you write in build() methods is just a lightweight, immutable description of UI widgets are cheap to create and thrown away on every rebuild. Flutter uses that description to update a parallel Element tree, which is long-lived and knows how to diff the new widget configuration against the old one (this is the reconciliation step, similar in spirit to React''s virtual DOM diffing).

Each Element that needs to draw something is backed by a RenderObject, which performs the actual layout (sizing and positioning) and painting (turning itself into drawing commands). Those drawing commands are handed to the engine (Skia or Impeller), which rasterizes them into pixels via the GPU. This three-tree split is why Flutter can skip expensive work: if a widget''s configuration hasn''t meaningfully changed, the element can reuse its existing render object instead of creating a new one.', NULL, NULL, '[]', '["If asked to go deeper, mention that `const` constructors let Flutter skip rebuilding a widget entirely because it can prove the instance is identical."]', '["what-is-flutter","const-widgets-flutter"]', '[]', '[]', 'published', '2026-08-27T13:00:56.875767+00:00', '2026-08-27T14:09:44.466281+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('b10f123c-0807-42de-ae1d-2a30063eced3', 'keys-in-flutter', 'What are Keys in Flutter and when do you need one?', 'Flutter Widgets', '["widgets","keys"]', 'Intermediate', 'A Key preserves a widget''s state and identity across rebuilds; you need one whenever Flutter could otherwise confuse two widgets of the same type at the same position, e.g. when reordering a list.', 'Flutter''s diffing algorithm matches new widgets to old elements primarily by type and position in the tree. When widgets of the same type sit at the same index across a rebuild, Flutter assumes they''re the same widget and just updates its properties, reusing the existing State object. This breaks down when a list of stateful widgets gets reordered, inserted into, or removed from — without a Key, Flutter matches by position, not identity, so state can appear to jump between items.

A ValueKey, ObjectKey, or UniqueKey tells Flutter''s reconciliation exactly which old element corresponds to which new widget, based on the key''s value rather than position. GlobalKey goes further, letting you access a widget''s State from anywhere and preserving it even if the widget moves to a completely different part of the tree.', 'dart', 'ListView.builder(
  itemCount: items.length,
  itemBuilder: (context, index) {
    final item = items[index];
    return Dismissible(
      key: ValueKey(item.id), // not index — id survives reordering
      onDismissed: (_) => removeItem(item),
      child: ListTile(title: Text(item.title)),
    );
  },
)', '["Using the list index as a Key instead of a stable identifier — this defeats the purpose since the index changes when items are reordered/removed.","Adding GlobalKeys everywhere ''just in case'' — they''re more expensive and should be reserved for cases that actually need cross-tree state access."]', '["Give the Dismissible/reorderable-list example specifically — it''s the classic scenario where missing Keys cause visible bugs."]', '["stateless-vs-stateful-widget"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('89132c20-07f8-43cc-975e-442e2f3f2fea', 'inherited-widget-explained', 'What is InheritedWidget and how does it enable state propagation?', 'Flutter Widgets', '["widgets","inheritedwidget"]', 'Advanced', 'InheritedWidget lets data be efficiently passed down the widget tree without manually threading it through every constructor, and it''s the low-level mechanism Provider, Theme, and MediaQuery are all built on.', 'A normal widget passes data to children only via constructor parameters, which gets unwieldy for data needed by many widgets at different depths (theme, locale, app-wide state). InheritedWidget solves this by making itself available to any descendant via context.dependOnInheritedWidgetOfExactType<T>() — the descendant registers as a dependent, and when the InheritedWidget rebuilds with different data, only the widgets that actually depend on it (not the whole subtree) rebuild.

The key method to override is updateShouldNotify(oldWidget), which decides whether dependents should rebuild — typically comparing the new and old data for equality. This selective-rebuild mechanism is exactly why Theme.of(context) or MediaQuery.of(context) are cheap to call in many widgets: only the ones whose relevant data actually changed re-render.', NULL, NULL, '["Calling dependOnInheritedWidgetOfExactType outside build() without it working as expected — it should be called from build or didChangeDependencies.","Assuming InheritedWidget rebuilds the entire subtree — it only rebuilds registered dependents."]', '["Mention that Provider, Theme.of, and MediaQuery.of are all built on InheritedWidget — shows you understand the layering, not just the Provider package in isolation."]', '["what-is-provider"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('5b2cc058-4619-415b-8f8f-f2cf14ee7d39', 'willpopscope-vs-popscope', 'How do you intercept the back button in Flutter?', 'Navigation & Routing', '["navigation"]', 'Intermediate', 'Wrap the screen in a PopScope widget (the modern replacement for the deprecated WillPopScope), setting canPop to false and handling the back attempt in the pop callback — commonly used for an ''unsaved changes'' confirmation dialog.', 'WillPopScope''s onWillPop callback returned a Future<bool> deciding whether the pop should proceed — but it was deprecated because it didn''t compose well with Navigator 2.0''s declarative model and predictive back gestures on Android. PopScope replaces it: set canPop: false to prevent the default pop, and inspect the pop attempt in its callback, from which you can show a confirmation dialog and call Navigator.pop() manually if the user confirms.', 'dart', 'PopScope(
  canPop: false,
  onPopInvokedWithResult: (didPop, result) async {
    if (didPop) return;
    final shouldPop = await showConfirmDialog(context);
    if (shouldPop && context.mounted) Navigator.pop(context);
  },
  child: const EditScreen(),
)', '["Still using the deprecated WillPopScope in new code instead of PopScope.","Setting canPop: false without ever actually popping programmatically afterward, permanently trapping the user on the screen."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('68006baf-9ac3-428f-83e9-4ffc10973b76', 'layoutbuilder-mediaquery-difference', 'What''s the difference between LayoutBuilder and MediaQuery for responsive design?', 'Flutter Widgets', '["widgets","responsive"]', 'Intermediate', 'MediaQuery gives you the entire screen/device''s size and metrics; LayoutBuilder gives you the constraints of just the specific widget it wraps, which is what you actually want for responsive decisions inside nested widgets.', 'MediaQuery.of(context).size returns the full screen dimensions, useful for app-wide decisions (tablet vs phone layout) but misleading inside a widget that isn''t full-screen — a widget inside a 300px-wide side panel has no way to know that from MediaQuery, since it doesn''t know about local layout constraints.

LayoutBuilder instead gives you a BoxConstraints object representing exactly how much space the parent has given this specific widget, via its builder callback. This makes it the correct tool for building a widget that adapts to whatever space it''s actually placed in, rather than assuming it occupies the full screen.', 'dart', 'LayoutBuilder(
  builder: (context, constraints) {
    if (constraints.maxWidth < 600) {
      return const MobileLayout();
    }
    return const TabletLayout();
  },
)', '["Using MediaQuery.of(context).size.width to decide a widget''s internal layout when the widget isn''t actually full-width.","Rebuilding on every MediaQuery change when only a specific dimension is needed — MediaQuery.of triggers a rebuild on any metric change (including keyboard insets) unless you select just the piece you need."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('3725ec8a-bc29-4bd9-89f9-b88e1482f4d7', 'form-validation-flutter', 'How do you implement form validation in Flutter?', 'Flutter Widgets', '["widgets","forms"]', 'Beginner', 'Wrap your fields in a Form widget with a GlobalKey<FormState>, give each TextFormField a validator function, and call formKey.currentState!.validate() to trigger all validators at once.', 'The Form widget acts as a container that can validate, save, and reset all of its descendant FormFields (like TextFormField) together. You attach a GlobalKey<FormState> to the Form so you can imperatively call methods on it — most importantly validate(), which runs every field''s validator callback and returns true only if all of them return null (no error).

Each TextFormField''s validator takes the current value and returns either an error string (shown under the field) or null (valid). onSaved callbacks let you collect all field values in one formKey.currentState!.save() call, convenient for building a data object from many fields at once.', 'dart', 'final _formKey = GlobalKey<FormState>();

Form(
  key: _formKey,
  child: Column(
    children: [
      TextFormField(
        validator: (value) {
          if (value == null || value.isEmpty) return ''Required'';
          if (!value.contains(''@'')) return ''Enter a valid email'';
          return null;
        },
      ),
      ElevatedButton(
        onPressed: () {
          if (_formKey.currentState!.validate()) {
            // all fields valid
          }
        },
        child: const Text(''Submit''),
      ),
    ],
  ),
)', '["Forgetting to wrap fields in a Form widget — validator only runs when Form.validate() is called.","Not calling setState() or using autovalidateMode when error messages should update live as the user types."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('2fc51927-f073-469a-a954-bba0878c209b', 'slivers-explained', 'What are Slivers in Flutter and when would you use CustomScrollView?', 'Flutter Widgets', '["widgets","slivers"]', 'Advanced', 'Slivers are scrollable areas that can be composed together inside a CustomScrollView, letting you mix different scroll behaviors — like a collapsing app bar, a grid, and a list — into one continuous scrollable, which a single ListView or GridView can''t do.', 'A regular ListView or GridView owns its entire scrollable area — you can''t easily mix a different kind of scrolling child (like a pinned header) inside it. CustomScrollView instead takes a list of slivers, each understanding how to lay itself out and paint within a shared scroll position: SliverAppBar (collapsing/pinned headers), SliverList, SliverGrid, SliverToBoxAdapter (wrapping a normal widget as a sliver).

This is the mechanism behind patterns like a large hero image that shrinks into a compact app bar as you scroll — SliverAppBar''s flexibleSpace handles exactly that, something awkward or impossible to build cleanly with plain widgets and a single scroll controller.', 'dart', 'CustomScrollView(
  slivers: [
    SliverAppBar(
      expandedHeight: 200,
      flexibleSpace: FlexibleSpaceBar(title: Text(''Profile'')),
      pinned: true,
    ),
    SliverList(
      delegate: SliverChildBuilderDelegate(
        (context, index) => ListTile(title: Text(''Item \$index'')),
        childCount: 20,
      ),
    ),
  ],
)', '["Trying to nest a ListView inside a CustomScrollView without wrapping it appropriately, causing ''unbounded height'' errors.","Reaching for CustomScrollView when a single ListView with a header widget would do — it adds complexity only worth it for genuinely mixed scroll behavior."]', '[]', '["listview-builder-optimization"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('94f6864e-a121-4ed0-b0ca-566d7c070c31', 'widget-composition-vs-inheritance', 'Why does Flutter favor composition over inheritance for building widgets?', 'Flutter Widgets', '["widgets","architecture"]', 'Intermediate', 'Flutter widgets are meant to be combined (composed) into new widgets rather than extended via subclassing, because composition keeps widgets small, reusable, and independently testable — Flutter''s own framework widgets are built this way.', 'You could subclass ElevatedButton and override its build method, but Flutter''s own widgets are deliberately shallow and specific — a Container, for example, is itself just composed internally of Padding, DecoratedBox, and other primitives. The idiomatic pattern for a ''custom button with extra behavior'' is to wrap or combine existing widgets into a new one, not extend a concrete widget class.

This matters practically: composed widgets can mix and match capabilities freely, while inheritance would force a rigid single-parent hierarchy. It also plays well with Flutter''s rebuild model — small, focused widgets rebuild cheaply and independently.', NULL, NULL, '["Subclassing StatelessWidget/StatefulWidget solely to extend framework widget behavior, when composing a new widget from existing ones would be idiomatic.","Building a single giant widget class instead of splitting it into smaller composed pieces."]', '["Reference that Container itself is a composed widget internally — a concrete example that shows real understanding, not just theory."]', '["flutter-architecture-overview"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('1879d361-28c0-4db3-b756-3fa045e1e170', 'hero-animations-flutter', 'How do Hero animations work in Flutter?', 'Flutter Widgets', '["widgets","animations"]', 'Intermediate', 'A Hero widget with a matching tag on two different screens tells Flutter to automatically animate that widget flying from its position on the first screen to its position on the second during a navigation transition.', 'When you push a new route, Flutter searches both the outgoing and incoming page''s widget trees for Hero widgets sharing the same tag. If it finds a matching pair, it removes both from their normal positions during the transition and animates a single widget moving and resizing between the two positions and sizes.

This is why Hero animations feel ''free'' — you don''t manually compute positions or sizes; Flutter''s navigator handles the interpolation as part of the standard page-route transition. It works with any push/pop using a route supporting hero animations (like MaterialPageRoute) — custom transitions may need explicit hero support.', 'dart', '// Screen A
Hero(tag: ''product-1'', child: Image.asset(''cover.png''))

// Screen B (pushed via Navigator)
Hero(tag: ''product-1'', child: Image.asset(''cover.png'', width: 300))', '["Using the same tag for multiple Hero widgets visible on the same screen — tags must be unique per screen or Flutter can''t match them correctly.","Expecting Hero to work across routes that don''t support the standard page-transition animation."]', '[]', '["flutter-animations-overview"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('ce52525e-5a54-4595-9073-d685713d025f', 'streamcontroller-broadcast-vs-single-subscription', 'What''s the difference between a broadcast StreamController and a single-subscription one?', 'Async Programming', '["dart","streams"]', 'Intermediate', 'A single-subscription StreamController allows only one listener ever, and buffers events until that listener subscribes; a broadcast StreamController allows multiple simultaneous listeners but doesn''t buffer events for listeners that subscribe late.', 'By default, StreamController() creates a single-subscription stream — appropriate for a one-time file read or a single HTTP response stream. Calling .listen() a second time throws a StateError.

StreamController.broadcast() supports any number of listeners, fitting use cases like a global event bus or a WebSocket connection multiple widgets observe. The tradeoff: broadcast streams don''t buffer events — if a listener subscribes after an event was already emitted, it simply misses that event. Choosing the right controller type upfront matters, since converting between them later requires re-architecting how the stream is consumed.', 'dart', '// Single-subscription — one listener only
final controller = StreamController<int>();

// Broadcast — many listeners, no buffering
final broadcastController = StreamController<int>.broadcast();', '["Calling .listen() twice on a single-subscription stream and being surprised by the StateError.","Assuming a broadcast stream replays past events to a newly-added listener — it doesn''t."]', '[]', '["future-vs-stream"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('afa1913c-f819-4495-a95f-5e8ab4d55b51', 'futurebuilder-common-pitfalls', 'What are the common pitfalls of using FutureBuilder?', 'Async Programming', '["widgets","futures"]', 'Intermediate', 'The most common FutureBuilder bug is passing a new Future instance on every build (e.g. calling a function directly in the future: parameter), which re-triggers the loading state on every rebuild instead of just once.', 'FutureBuilder re-runs its builder whenever the widget rebuilds, but only actually re-fetches if the future instance it''s given is a different Future than last time. Writing future: fetchData() directly inside build() creates a brand-new Future object on every rebuild — even ones triggered by unrelated state changes — causing the UI to flash back to a loading spinner repeatedly.

The fix is to create the Future once (in initState, or a stored state variable) and pass that same stored reference into future: on every build. This is conceptually the same fix as a common useEffect dependency-array mistake in React.', 'dart', 'class _MyWidgetState extends State<MyWidget> {
  late final Future<Data> _future = fetchData(); // created once

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Data>(
      future: _future, // stable reference across rebuilds
      builder: (context, snapshot) { /* ... */ return const SizedBox(); },
    );
  }
}', '["Calling the async function directly inside the future: parameter on every build.","Not handling ConnectionState.none/waiting/done explicitly, leading to a flash of incorrect UI between states."]', '["This is a commonly-asked ''gotcha'' — mentioning the new-Future-per-build issue signals real hands-on debugging experience."]', '["future-vs-stream"]', '["flutter-rest-api-dio-riverpod"]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('375f47ed-c305-4468-bc99-8de571ba68c1', 'dart-completer-explained', 'What is a Completer in Dart and when would you use one?', 'Async Programming', '["dart","futures"]', 'Advanced', 'A Completer lets you manually create and control a Future, resolving it later with .complete() or .completeError() — useful for wrapping callback-based APIs into a Future-based one.', 'Normally you get a Future by calling an async function, but sometimes you need to bridge a callback-style API (a native plugin, an event listener) into Future-based code. Completer<T>() gives you a .future property you can return immediately, and separately, you call .complete(value) (or .completeError(error)) once, whenever the actual result becomes available.

This pattern is common when wrapping platform channel callbacks, converting a one-off Stream event into a Future, or adding a timeout race to an operation that doesn''t natively support one.', 'dart', 'Future<String> waitForCallback() {
  final completer = Completer<String>();
  someCallbackApi.onResult((result) {
    completer.complete(result);
  });
  return completer.future;
}', '["Calling .complete() more than once on the same Completer — this throws a StateError, since a Future can only resolve once.","Using a Completer when a plain async function would do."]', '[]', '["dart-async-await"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('5c6fcc91-65d7-47aa-be1d-45d9e1393965', 'dart-zones-explained', 'What are Zones in Dart used for?', 'Async Programming', '["dart","error-handling"]', 'Advanced', 'A Zone is an execution context that lets you intercept and customize behaviors like error handling, print output, and timers for all code running within it — most commonly used to catch otherwise-uncaught async errors app-wide.', 'Dart''s runZonedGuarded() lets you run a block of code (typically your entire main()/runApp() call) inside a zone with a custom error handler, catching errors that would otherwise crash the app silently — particularly errors thrown in async callbacks that aren''t wrapped in a try/catch, which a regular try/catch around runApp() wouldn''t catch.

This is the standard pattern for wiring up crash reporting (Firebase Crashlytics, Sentry) so genuinely unhandled async errors still get reported instead of just appearing in the console or crashing silently in release mode.', 'dart', 'void main() {
  runZonedGuarded(() {
    runApp(const MyApp());
  }, (error, stackTrace) {
    // report to Crashlytics/Sentry
  });
}', '["Assuming a top-level try/catch around runApp() catches all async errors — it doesn''t catch errors in callbacks scheduled after the initial synchronous call completes.","Not also setting FlutterError.onError for framework-level errors — runZonedGuarded alone doesn''t catch those; both are typically wired together."]', '["Mention that runZonedGuarded + FlutterError.onError together is the standard ''catch everything for crash reporting'' pattern."]', '["flutter-memory-management"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('d0a17ac7-38dd-4a69-ab62-df96c22a3716', 'timer-vs-future-delayed', 'What''s the difference between Timer and Future.delayed?', 'Async Programming', '["dart","timers"]', 'Beginner', 'Future.delayed runs a callback once after a delay and resolves; Timer can either fire once (Timer()) or repeatedly (Timer.periodic()), and importantly gives you a handle you can explicitly cancel.', 'Future.delayed(duration, callback) is a one-shot delayed action expressed as a Future — convenient when you just need to await a pause or chain a delayed step into async code. It has no built-in way to cancel it once started.

Timer(duration, callback) does the same one-shot job but returns a Timer object with a .cancel() method, which matters when the delayed action might need to be aborted (e.g. a debounce timer that should reset if the user types again). Timer.periodic(duration, callback) repeats indefinitely until cancelled — the standard tool for polling or a repeating countdown, and one that must be cancelled in dispose() to avoid leaking.', 'dart', '// One-shot, no cancellation needed
Future.delayed(const Duration(seconds: 2), () => print(''done''));

// Cancellable debounce timer
Timer? _debounce;
void onSearchChanged(String query) {
  _debounce?.cancel();
  _debounce = Timer(const Duration(milliseconds: 300), () => search(query));
}', '["Using Future.delayed for a debounce pattern where you need to cancel a pending call — only Timer can be cancelled.","Forgetting to cancel a Timer.periodic in dispose(), leaking a repeating callback indefinitely."]', '[]', '["flutter-memory-management"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('fcd5520a-a2a8-4142-b7b8-d3bfbf7680de', 'async-generator-functions-dart', 'What are async* generator functions in Dart?', 'Async Programming', '["dart","streams"]', 'Advanced', 'An async* function is a generator that returns a Stream instead of a Future, letting you yield multiple values over time using the same imperative, sequential-looking code style as a normal async function.', 'A regular async function returns a single Future and uses return once. An async* function returns a Stream<T> and can yield a value any number of times, pausing between yields exactly like await pauses a Future — without needing to manually construct a StreamController and call .add() on it.

This is the cleanest way to write a Stream when values are naturally produced in a loop or sequence — for example, reading lines from a growing log file, or emitting incremental progress updates during a long computation.', 'dart', 'Stream<int> countDown(int from) async* {
  for (int i = from; i > 0; i--) {
    await Future.delayed(const Duration(seconds: 1));
    yield i;
  }
}

// Usage
await for (final n in countDown(3)) {
  print(n); // 3, 2, 1 — one per second
}', '["Reaching for a manual StreamController when an async* generator would express the same logic more simply.","Forgetting yield* (yield-each) is needed to delegate to another Stream inside an async* function, versus plain yield for a single value."]', '[]', '["future-vs-stream"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('ac9ae33b-db5f-4cf3-91ef-6bec23a78779', 'navigator-1-vs-navigator-2', 'What''s the difference between Navigator 1.0 and Navigator 2.0?', 'Navigation & Routing', '["navigation"]', 'Advanced', 'Navigator 1.0 is imperative — you push/pop routes as commands; Navigator 2.0 is declarative — you describe the current stack of pages as a list derived from app state, which is what enables deep linking and browser back-button support to work correctly.', 'With Navigator 1.0''s Navigator.push()/Navigator.pop(), the navigation stack is built up imperatively as a side effect of your code running — there''s no single source of truth describing ''what the stack currently looks like,'' making browser URLs, deep links, and state restoration awkward since you''d need to manually replay a sequence of pushes to reach an arbitrary state.

Navigator 2.0 introduces Router, RouterDelegate, and RouteInformationParser: you maintain your own app state, and the Navigator widget''s pages list is derived from that state declaratively. This makes it possible to jump directly to a deep-linked state, since the pages list can be constructed for any given URL without replaying pushes.

In practice, most apps use go_router (built on Navigator 2.0) rather than the raw API directly, since it hides most of the boilerplate behind a simpler declarative route table.', NULL, NULL, '["Believing Navigator 2.0 replaced Navigator 1.0 — the imperative push/pop API still works and is fine for apps that don''t need deep linking/URL sync.","Hand-rolling raw Navigator 2.0 for a simple app instead of reaching for go_router."]', '["Mention go_router specifically — most real-world Flutter apps use it rather than raw Navigator 2.0."]', '["go-router-basics"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('5c86b563-ac2a-4827-9837-3d92992ab4b2', 'go-router-basics', 'How does go_router simplify navigation in Flutter?', 'Navigation & Routing', '["navigation","go_router"]', 'Intermediate', 'go_router lets you define your app''s routes as a declarative table mapping URL paths to pages, handling deep linking, web URL sync, and nested/shell routes without writing raw Navigator 2.0 boilerplate.', 'You define a GoRouter with a list of GoRoute entries, each specifying a path and a builder returning the page widget for that path — including path parameters (/users/:id) and query parameters, both accessible via state. Navigating is as simple as context.go(''/users/5'') or context.push(''/settings''), and go_router keeps the browser URL in sync automatically on Flutter Web.

It also supports ShellRoute for persistent UI (like a bottom nav bar that stays while inner content changes) and redirect logic (e.g. redirecting to login if unauthenticated), both notoriously fiddly to implement correctly with raw Navigator 2.0.', 'dart', 'final router = GoRouter(
  routes: [
    GoRoute(path: ''/'', builder: (context, state) => const HomeScreen()),
    GoRoute(
      path: ''/users/:id'',
      builder: (context, state) {
        final id = state.pathParameters[''id'']!;
        return UserScreen(userId: id);
      },
    ),
  ],
);

// Navigate
context.go(''/users/5'');', '["Mixing go_router navigation with raw Navigator.push in the same app inconsistently, causing confusing back-stack behavior.","Not using redirect for auth guarding and instead manually checking auth state in every screen''s initState."]', '[]', '["navigator-1-vs-navigator-2"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('57de9dc6-8714-4b6e-8a4c-152ad2babcc5', 'named-routes-vs-materialpageroute', 'Should you use named routes or MaterialPageRoute directly?', 'Navigation & Routing', '["navigation"]', 'Beginner', 'Named routes work well for simple, static navigation with no arguments; MaterialPageRoute pushed directly is more flexible for passing complex objects — though most new apps reach for go_router instead of either.', 'Navigator.pushNamed(context, ''/details'') looks up a route by string name in a table defined in MaterialApp(routes: {...}). It''s concise, but passing data requires either a generic arguments object (losing compile-time type safety) or global state.

Navigator.push(context, MaterialPageRoute(builder: (context) => DetailScreen(item: item))) passes strongly-typed data directly as a constructor parameter, safer and easier to refactor, at the cost of slightly more verbose call sites. For apps beyond a handful of screens, most teams now skip both in favor of go_router''s typed path/query parameters.', NULL, NULL, '["Passing complex objects through named routes'' arguments as Object? and casting them unsafely in the destination screen.","Registering every screen as a named route even when the app never needs deep linking or URL-based navigation."]', '[]', '["go-router-basics"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('6a5b7e57-b4c8-4153-9c0b-331fe0303088', 'deep-linking-flutter', 'How does deep linking work in Flutter?', 'Navigation & Routing', '["navigation","deep-linking"]', 'Advanced', 'Deep linking means the OS can open your app directly to a specific screen from an external URL or link tap, requiring platform-level configuration (Android intent filters, iOS Universal Links) in addition to in-app routing logic mapping the incoming URL to the right screen.', 'On Android, you declare an intent-filter in AndroidManifest.xml specifying the scheme/host your app should handle (either a custom scheme like myapp:// or, for Android App Links, https://yourdomain.com with domain verification via a hosted assetlinks.json file). On iOS, Universal Links require an associated domain entitlement plus a hosted apple-app-site-association file proving domain ownership — without it, iOS won''t route the link to your app.

Once the OS hands the URL to your app, your routing layer (commonly go_router, which has built-in deep-link support) parses the incoming path and navigates to the corresponding screen — the in-app part is the easy half; platform-level domain verification is usually where deep linking actually breaks in practice.', NULL, NULL, '["Testing only custom URL schemes and assuming https Universal Links/App Links will work the same way — they require separate domain verification setup.","Forgetting to host the required verification file at the exact expected path on the domain, which silently breaks App Links/Universal Links."]', '["Distinguish custom URL schemes (simpler, no domain verification) from Universal Links/App Links (require hosted verification files)."]', '["go-router-basics"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('42a9a36e-0b23-4d3d-b6cf-83a8c7157c7e', 'nested-navigation-flutter', 'How do you implement nested navigation in Flutter (e.g. a bottom nav bar with separate stacks per tab)?', 'Navigation & Routing', '["navigation"]', 'Advanced', 'Give each tab its own Navigator with a unique key, so each tab maintains an independent back stack, and wrap it in an IndexedStack to preserve each tab''s state when switching between them.', 'A naive bottom-nav implementation swaps the body widget based on the selected index, resetting each tab''s navigation state (and scroll position) every time you switch away and back. The fix: give each tab its own Navigator (each with a distinct GlobalKey<NavigatorState>), nested inside an IndexedStack (which keeps all tabs'' widget trees alive, just hidden) — so switching tabs doesn''t rebuild or reset them.

go_router''s StatefulShellRoute is the modern, purpose-built solution for exactly this pattern, handling the multiple-Navigator-plus-IndexedStack wiring for you.', 'dart', 'IndexedStack(
  index: currentTabIndex,
  children: [
    Navigator(key: tab1NavigatorKey, onGenerateRoute: onGenerateRoute1),
    Navigator(key: tab2NavigatorKey, onGenerateRoute: onGenerateRoute2),
  ],
)', '["Using a plain Stack/conditional widget swap for bottom-nav tabs instead of IndexedStack, causing each tab''s state and scroll position to reset on every switch.","Sharing a single Navigator across all tabs, so pushing a screen in one tab affects the whole app''s back button behavior instead of just that tab."]', '[]', '["go-router-basics"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('f1bdbadf-dbf0-494d-aa57-5c248677771b', 'passing-data-back-with-pop', 'How do you return data from a screen when popping it?', 'Navigation & Routing', '["navigation"]', 'Beginner', 'Pass a value to Navigator.pop(context, value), and await the result of the original Navigator.push call — the awaited Future resolves with whatever value was passed to pop.', 'Navigator.push returns a Future that doesn''t resolve until the pushed route is popped. If you await that push call, and the pushed screen calls Navigator.pop(context, someValue) instead of just Navigator.pop(context), the awaited Future resolves with someValue — a clean, typed way to get a result back from a screen without callbacks or global state.', 'dart', '// Caller
final result = await Navigator.push<String>(
  context,
  MaterialPageRoute(builder: (context) => const PickerScreen()),
);
if (result != null) print(''Picked: \$result'');

// PickerScreen
Navigator.pop(context, ''selected-value'');', '["Forgetting to specify the generic type on Navigator.push<T>, causing the awaited result to be typed as dynamic/Object? unnecessarily.","Not handling the null case when the user backs out without picking anything — pop() with no argument resolves the Future with null."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('7e7a2dbf-40b2-4f87-8944-4b46de78a982', 'flutter-widget-testing-basics', 'How do you write a basic widget test in Flutter?', 'Testing', '["testing"]', 'Beginner', 'Use testWidgets() with a WidgetTester, pump your widget with tester.pumpWidget(), then use finders (like find.text or find.byType) combined with matchers (like findsOneWidget) to assert on what''s rendered.', 'Widget tests run in a simulated environment (no real device needed) and are faster than full integration tests while still testing actual widget rendering and interaction, unlike pure unit tests. tester.pumpWidget(widget) builds the widget tree; tester.pump() advances a single frame (needed after state changes); tester.pumpAndSettle() repeatedly pumps until no more frames are scheduled, useful for animations to finish.

find.text(''Login''), find.byType(ElevatedButton), and find.byKey(someKey) locate widgets, and expect(finder, findsOneWidget) (or findsNothing, findsNWidgets(n)) asserts on what''s present.', 'dart', 'testWidgets(''shows error on empty submit'', (tester) async {
  await tester.pumpWidget(const MaterialApp(home: LoginScreen()));

  await tester.tap(find.text(''Submit''));
  await tester.pump();

  expect(find.text(''Email is required''), findsOneWidget);
});', '["Forgetting to wrap the widget under test in a MaterialApp, causing errors about missing Directionality/Theme ancestors.","Using tester.pump() when tester.pumpAndSettle() is needed (e.g. after a navigation transition or animation), leading to flaky assertions."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('596a93ec-210f-43e1-9bac-8d886fc67cdc', 'mocking-with-mocktail', 'How do you mock dependencies in Flutter tests?', 'Testing', '["testing","mocking"]', 'Intermediate', 'Use the mocktail package (or mockito) to create a fake implementation of a class/interface, stub its methods with when().thenAnswer(), and inject the mock wherever the real dependency would normally be provided.', 'For a class under test that depends on a repository or API client, you don''t want your unit test making real network calls. mocktail lets you write class MockUserRepository extends Mock implements UserRepository {}, then stub specific method calls with when(() => mock.getUser(any())).thenAnswer((_) async => testUser).

The class under test then receives the mock via constructor injection — exactly why dependency injection matters for testability — and you can assert on how it was called with verify(() => mock.getUser(''123'')).called(1).', 'dart', 'class MockUserRepository extends Mock implements UserRepository {}

void main() {
  late MockUserRepository mockRepo;

  setUp(() {
    mockRepo = MockUserRepository();
  });

  test(''returns user from repository'', () async {
    when(() => mockRepo.getUser(''1'')).thenAnswer((_) async => User(id: ''1'', name: ''Ana''));

    final result = await mockRepo.getUser(''1'');

    expect(result.name, ''Ana'');
    verify(() => mockRepo.getUser(''1'')).called(1);
  });
}', '["Testing a class that constructs its own dependencies internally instead of receiving them via constructor injection — this makes mocking impossible without refactoring.","Forgetting to register a fallback value for custom argument types when using any() with mocktail, which throws at runtime."]', '[]', '["dependency-injection-flutter"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('f48d5822-7c27-44e4-9951-4055f71f90e8', 'golden-tests-flutter', 'What are golden tests in Flutter?', 'Testing', '["testing"]', 'Advanced', 'Golden tests render a widget and compare a screenshot of it pixel-for-pixel against a previously-approved reference image (''golden file''), catching unintended visual regressions that logic-based widget tests can''t detect.', 'A normal widget test checks things like ''does this text exist'' — it says nothing about whether the widget actually looks right. matchesGoldenFile() in a widget test renders the widget, captures it as an image, and compares it byte-for-byte against a stored PNG. The first run generates the golden file (via flutter test --update-goldens); subsequent runs fail if rendering has changed, requiring a human to review whether the change was intentional or a real regression.

Golden tests are sensitive to font rendering and platform differences, so teams typically run them in CI on a consistent environment to avoid false failures.', 'dart', 'testWidgets(''button matches golden'', (tester) async {
  await tester.pumpWidget(const MaterialApp(home: MyButton()));
  await expectLater(
    find.byType(MyButton),
    matchesGoldenFile(''goldens/my_button.png''),
  );
});', '["Running golden tests locally on a different OS/font setup than CI, causing constant false failures from anti-aliasing differences.","Blindly re-generating goldens without reviewing the visual diff first — this can silently accept a real regression."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('42407d76-7bc1-4f8a-97c6-49179a9ca39b', 'integration-test-package', 'What is the integration_test package used for?', 'Testing', '["testing"]', 'Intermediate', 'integration_test runs your app as a whole on a real device or emulator, driving it through full user flows end-to-end — unlike widget tests, which run in a simulated environment without a real platform underneath.', 'Widget tests are fast but don''t exercise real platform channels, real plugins, or actual device behavior. integration_test (Flutter''s official successor to flutter_driver) runs your actual compiled app on a real or emulated device, using the same WidgetTester API as widget tests but backed by real app and platform integration — so a test can genuinely tap through login, fetch data, and navigate multiple real screens.

These tests are slower and more brittle than widget tests, so most teams use a testing pyramid: many unit tests, a good number of widget tests, and a smaller set of integration tests covering only the most critical user flows.', NULL, NULL, '["Trying to replace all widget tests with integration tests — they''re much slower and better reserved for a handful of critical end-to-end flows.","Not accounting for real network/animation timing, leading to flaky integration tests."]', '[]', '["flutter-widget-testing-basics"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('62e44704-7491-4177-9905-6c2b12e340cc', 'testing-riverpod-providers', 'How do you test code that uses Riverpod providers?', 'Testing', '["testing","riverpod"]', 'Intermediate', 'Wrap the widget or logic under test in a ProviderScope with overrides — swapping real providers for test doubles via overrideWith or overrideWithValue — so tests never hit real network/database calls.', 'Riverpod''s ProviderScope accepts an overrides list, letting you replace any provider with a fake implementation just for that scope. For a repository provider: overrides: [userRepositoryProvider.overrideWithValue(mockRepo)]. For an AsyncNotifierProvider with its own async logic, overrideWith lets you substitute the whole provider''s implementation.

This makes it possible to test a widget''s behavior across loading/data/error states deterministically, by overriding a provider to immediately return each state, rather than depending on real timing from an actual async call.', 'dart', 'testWidgets(''shows user name when loaded'', (tester) async {
  await tester.pumpWidget(
    ProviderScope(
      overrides: [
        userRepositoryProvider.overrideWithValue(MockUserRepository()),
      ],
      child: const MaterialApp(home: ProfileScreen()),
    ),
  );
  await tester.pumpAndSettle();
  expect(find.text(''Ana''), findsOneWidget);
});', '["Using overrideWithValue for a provider whose behavior (not just its value) needs to change between tests — overrideWith gives a full replacement implementation.","Forgetting that a fresh ProviderScope is needed per test to avoid state leaking between tests."]', '[]', '["riverpod-vs-provider"]', '["flutter-state-management-provider-vs-riverpod-vs-bloc"]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('ff233f35-f958-438b-8b4c-7be172eb2af3', 'testing-bloc-cubit', 'How do you unit test a Bloc or Cubit?', 'Testing', '["testing","bloc"]', 'Intermediate', 'Use the bloc_test package''s blocTest() helper, which lets you set up a Bloc, feed it events (or call Cubit methods), and assert on the exact sequence of emitted states — without needing any widget tree at all.', 'Because Blocs and Cubits are pure Dart classes with no Flutter dependency, they''re naturally easy to unit test — no pumpWidget or WidgetTester needed. bloc_test''s blocTest() reduces the boilerplate of the arrange-act-assert pattern: a build function creating the Bloc, an act function dispatching events, and an expect function returning the list of states you expect to be emitted, in order.', 'dart', 'blocTest<CounterBloc, int>(
  ''emits [1] when Increment is added'',
  build: () => CounterBloc(),
  act: (bloc) => bloc.add(Increment()),
  expect: () => [1],
);', '["Testing Blocs by manually subscribing to the stream and asserting outside blocTest, reinventing what the helper already does more concisely.","Forgetting that blocTest''s expect checks the states emitted during act, not the full history including the initial state."]', '[]', '["bloc-pattern-explained"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('10bf5645-ea34-4caf-875b-818708a683ee', 'pump-vs-pumpandsettle', 'What''s the difference between tester.pump() and tester.pumpAndSettle()?', 'Testing', '["testing"]', 'Beginner', 'pump() advances the clock by one frame (or a given duration); pumpAndSettle() repeatedly pumps frames until there are no more scheduled frames, which is more convenient but can hang or time out if something schedules frames indefinitely.', 'After an action like tapping a button, Flutter doesn''t rebuild synchronously — you need to pump() to process the resulting frame. For a single state update, one pump() is enough. For anything involving animation or a transition, you''d need many pumps to reach the final settled state — pumpAndSettle() automates that by looping pump() calls until no new frames are scheduled.

The catch: pumpAndSettle() will throw a timeout if something keeps scheduling frames indefinitely, such as an infinitely-repeating animation (a loading spinner) — in that case you must use explicit pump(duration) calls instead.', NULL, NULL, '["Always reaching for pumpAndSettle() out of habit, then getting a confusing timeout on a screen with an infinite/repeating animation.","Using a single pump() when a multi-step animation/transition genuinely needs multiple frames to reach its final state."]', '[]', '["flutter-widget-testing-basics"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('0fcdb2d3-df49-4a01-aa25-3b4aac9e6210', 'test-coverage-flutter', 'How do you measure test coverage in a Flutter project?', 'Testing', '["testing"]', 'Beginner', 'Run flutter test --coverage to generate a lcov.info file, then use a tool like genhtml (from lcov) or an editor extension to turn it into a readable report showing exactly which lines are covered.', 'flutter test --coverage runs your whole test suite and outputs coverage/lcov.info in the standard lcov format, which most CI coverage tools (Codecov, Coveralls) and local viewers understand natively. To view it as an HTML report locally: genhtml coverage/lcov.info -o coverage/html, then open coverage/html/index.html.

Coverage percentage is a useful signal but not a goal in itself — 100% line coverage doesn''t guarantee correctness, so it''s best used to find obviously-untested code paths rather than as a strict quality gate.', NULL, NULL, '["Treating a high coverage percentage as proof of correctness rather than just ''this code executed during some test.''","Not excluding generated files (*.g.dart, *.freezed.dart) from coverage reports, which skews the percentage misleadingly low."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('a1c4e772-1f97-4f7e-a020-64dea83cbb55', 'dart-records', 'What are Records in Dart and when would you use one?', 'Dart Questions', '["dart","records"]', 'Intermediate', 'A Record is a built-in, anonymous, immutable data structure that groups multiple values together — useful for returning multiple values from a function without declaring a dedicated class.', 'Before Records (Dart 3), returning ''two values'' from a function meant either creating a small class, using a List/Map (losing type safety), or a Tuple package. Records solve this natively: (int, String) parseEntry() => (200, ''OK''); returns a record you can destructure with pattern matching: final (code, message) = parseEntry();

Records also support named fields — ({int code, String message}) — for clarity when position alone isn''t descriptive. Unlike classes, Records are structurally typed and compared by value, not identity, making them convenient for lightweight groupings that don''t need custom behavior or identity semantics.', 'dart', '(double, double) minMax(List<double> values) {
  return (values.reduce(min), values.reduce(max));
}

final (lowest, highest) = minMax([3, 1, 4, 1, 5]);
print(''Range: \$lowest to \$highest'');', '["Reaching for a Record when a proper class with named, semantically meaningful fields and methods would communicate intent better.","Forgetting Records are compared structurally by value, which is usually desired but can surprise if identity was expected."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('0a303b35-161f-4c77-a1eb-17d1dee0a811', 'dart-sealed-classes-pattern-matching', 'What are sealed classes in Dart and how do they enable exhaustive pattern matching?', 'Dart Questions', '["dart","pattern-matching"]', 'Advanced', 'A sealed class restricts which classes can extend/implement it to only those defined in the same library, letting the compiler verify a switch statement handles every possible subtype — catching missing cases at compile time instead of runtime.', 'Before sealed classes, an abstract class could be extended anywhere, so a switch over its subtypes could never be proven exhaustive by the compiler — you always needed a default case, even after covering every known subtype, because a new one could appear from an unrelated file.

Declaring sealed class Result<T> {} with subclasses Success<T> and Failure<T> in the same file tells the compiler that''s the complete set. A switch (result) { Success(:final data) => ..., Failure(:final error) => ... } is then exhaustive — if a third subclass is added later and a case is missed, the compiler errors immediately instead of silently falling through at runtime. This is the modern Dart-native alternative to encoding a result-or-error union type, replacing patterns that previously needed the freezed package.', 'dart', 'sealed class Result<T> {}
class Success<T> extends Result<T> { final T data; Success(this.data); }
class Failure<T> extends Result<T> { final String error; Failure(this.error); }

String describe(Result<int> result) => switch (result) {
  Success(:final data) => ''Got \$data'',
  Failure(:final error) => ''Error: \$error'',
}; // exhaustive — no default needed', '["Adding a redundant default case to an already-exhaustive sealed-class switch, defeating the compiler''s ability to catch a missed case later.","Confusing sealed with abstract — sealed additionally restricts subclassing to the same library."]', '["Mention this reduces the need for the freezed package''s union-type codegen for simple cases."]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('71a634f4-93ad-452c-8e4f-0926928ff192', 'dart-late-keyword', 'What does the late keyword do in Dart, and what''s a common mistake with it?', 'Dart Questions', '["dart","null-safety"]', 'Beginner', 'late tells the compiler a non-nullable variable will definitely be assigned before use, even though it can''t verify that at compile time — deferring the null-safety check to runtime, where accessing it before assignment throws a LateInitializationError.', 'Sound null safety normally requires the compiler to prove a non-nullable variable is initialized before use. Sometimes that''s genuinely not knowable at compile time — e.g. a controller initialized in initState() rather than at declaration. late is an escape hatch: you promise the variable will be set before any read, and the compiler trusts you instead of proving it.

The common mistake is using late as a workaround to silence a null-safety error without actually guaranteeing initialization happens first — this converts a compile-time safety net into a runtime crash (LateInitializationError) if the assumption is wrong.', 'dart', 'class _MyWidgetState extends State<MyWidget> {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this); // set before any read
  }
}', '["Using late to suppress a null-safety compiler error without verifying the initialization ordering actually holds.","Using late for a value that''s genuinely optional — it should be nullable (T?) instead."]', '[]', '["dart-null-safety"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('896e0640-fe3c-4c75-bea2-d8e5cab06ad8', 'dart-factory-constructors', 'What is a factory constructor in Dart and when would you use one?', 'Dart Questions', '["dart","constructors"]', 'Intermediate', 'A factory constructor can return an existing instance instead of always creating a new one, or return a subtype — useful for caching/singleton patterns and for fromJson constructors that might return different subclasses based on the data.', 'A normal constructor always creates a new instance of exactly its own class. A factory constructor is a static-like method that must return some instance of the type (or a subtype), giving you control over instantiation — you could return a cached instance, look one up from a pool, or decide which of several subclasses to instantiate based on input.

The most common real-world use is a fromJson factory on a class hierarchy: factory Shape.fromJson(json) => switch (json[''type'']) { ''circle'' => Circle.fromJson(json), ... } — something a regular constructor can''t do, since it could never return a different subclass instance.', 'dart', 'class Logger {
  static final Map<String, Logger> _cache = {};

  factory Logger(String name) {
    return _cache.putIfAbsent(name, () => Logger._internal(name));
  }

  Logger._internal(this.name);
  final String name;
}', '["Assuming factory constructors can access this like a normal constructor — they can''t, since they might not even create a new instance.","Overusing the singleton-via-factory pattern for things that would be simpler and more testable as an injected dependency."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('38ba2296-8724-4fe7-b3f7-cb925857e7c0', 'dart-generics-explained', 'How do generics work in Dart and why are they useful?', 'Dart Questions', '["dart","generics"]', 'Intermediate', 'Generics let a class or function be written once and work with any type, while still giving compile-time type safety — List<String> and List<int> are both Lists, but the compiler prevents mixing types into either.', 'Without generics, a collection would either be locked to one specific type or typed as dynamic/Object (losing compile-time safety, requiring casts everywhere). class Box<T> { T value; Box(this.value); } lets Box<int> and Box<String> share one implementation while the compiler still enforces that a Box<int>''s value is always an int.

Generic bounds (class NumberBox<T extends num> {}) further restrict which types are valid, letting you call methods specific to that bound inside the generic class body.', 'dart', 'class Repository<T> {
  final List<T> _items = [];
  void add(T item) => _items.add(item);
  List<T> getAll() => List.unmodifiable(_items);
}

final userRepo = Repository<User>();
userRepo.add(User(name: ''Ana'')); // type-checked at compile time', '["Using dynamic instead of a proper generic type parameter, silently losing compile-time type checking.","Not adding a bound (extends) when the generic type needs to support specific operations, then working around it with unsafe casts."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('3e4f23b8-43be-4805-a543-944869d64467', 'riverpod-code-generation', 'What does Riverpod''s code generation (@riverpod annotation) add over manually-declared providers?', 'State Management', '["riverpod"]', 'Intermediate', 'The @riverpod annotation (via riverpod_generator) generates the provider boilerplate for you from a plain function or class, reducing verbosity and catching more mistakes at compile time, at the cost of needing a code-generation build step.', 'Manually declaring final userProvider = FutureProvider<User>((ref) => fetchUser()); works fine, but as an app grows, choosing the right provider type for each case adds boilerplate. With @riverpod, you write a plain annotated function: @riverpod Future<User> user(UserRef ref) => fetchUser(); and the generator produces the correctly-typed provider automatically, inferring the right variant from your function''s return type.

The practical gotcha: this requires running dart run build_runner watch --delete-conflicting-outputs during development so generated .g.dart files stay in sync — forgetting this leaves you editing a provider whose generated code is stale, causing confusing type errors unrelated to your actual change.', 'dart', '// user_provider.dart
part ''user_provider.g.dart'';

@riverpod
Future<User> user(UserRef ref) async {
  return ref.watch(userRepositoryProvider).getUser();
}', '["Forgetting to run build_runner in watch mode during development, then being confused by type errors referencing outdated generated code.","Committing the generated .g.dart files inconsistently across a team without a deliberate decision."]', '["Mentioning the build_runner watch-mode requirement specifically signals real hands-on usage."]', '["riverpod-vs-provider"]', '["flutter-state-management-provider-vs-riverpod-vs-bloc"]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('61c80038-7a17-4087-a97e-3a883c96b183', 'bloc-vs-cubit', 'What''s the difference between Bloc and Cubit?', 'State Management', '["bloc"]', 'Intermediate', 'Cubit is a simplified version of Bloc — you call methods directly to emit new states, instead of dispatching Events that get mapped to states — trading some of Bloc''s structure and traceability for less boilerplate.', 'A full Bloc requires defining Event classes and an on<Event>() handler mapping each event to emitted states — verbose, but it creates a clear, replayable log of exactly what triggered each state change. Cubit skips the Event layer entirely: you call a method like counterCubit.increment(), which directly calls emit(state + 1) inside its body.

The practical tradeoff: Cubit is faster to write and easier to understand for simple state, but you lose the explicit, named ''what caused this'' record that Bloc''s events provide — which matters more as business logic gets complex or when you want event-replay debugging.', 'dart', 'class CounterCubit extends Cubit<int> {
  CounterCubit() : super(0);
  void increment() => emit(state + 1);
}

// Usage
context.read<CounterCubit>().increment();', '["Choosing Bloc for a trivial toggle/counter where Cubit''s simplicity would suffice.","Choosing Cubit for genuinely complex business logic where Bloc''s explicit events would make the code far easier to trace and test."]', '[]', '["bloc-pattern-explained"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('b51a409b-84da-4c97-803e-6832131c1ef2', 'getx-obx-reactivity-internals', 'How does GetX''s Obx widget know when to rebuild?', 'State Management', '["getx"]', 'Advanced', 'Obx subscribes to any .obs observable read inside its builder function during the build — it tracks reads via a global tracking mechanism, rather than requiring you to explicitly declare which values it depends on.', 'Unlike Provider''s Consumer<T> (explicitly typed to one provider) or Riverpod''s ref.watch() (explicitly registers a dependency per call), GetX''s Obx(() => Text(''\${counter.value}'')) figures out its dependencies implicitly: when the builder function runs, reading .value on any Rx/.obs variable registers that observable with the currently-building Obx instance, similar in spirit to how MobX or Vue''s reactivity system works.

In practice, this means Obx only rebuilds when an observable it actually read last time changes — but it can''t detect a dependency it didn''t read on the previous build (e.g. a value only read inside a conditional branch that wasn''t taken), a subtle source of ''why didn''t this rebuild'' bugs.', NULL, NULL, '["Reading an observable conditionally inside Obx, then being surprised the widget doesn''t rebuild when that branch wasn''t taken during the last build.","Nesting Obx widgets unnecessarily instead of one Obx wrapping the whole reactive section."]', '[]', '["getx-state-management"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('5dd89685-a42d-406e-bb02-0c7aceee7625', 'provider-proxyprovider', 'What is ProxyProvider used for in the Provider package?', 'State Management', '["provider"]', 'Advanced', 'ProxyProvider lets you create a provider whose value depends on one or more other providers above it — for example, building a repository that needs an already-provided API client.', 'A plain Provider creates a value independently. ProxyProvider<ApiClient, UserRepository>((context, apiClient, previous) => UserRepository(apiClient)) instead builds its value from another provider''s value, re-running the builder whenever the upstream ApiClient provider changes. This is how you express a dependency chain declaratively: AuthProvider → ApiClient → UserRepository, wired together via nested/MultiProvider ProxyProviders.

The previous parameter lets you reuse or dispose of the prior value manually if needed, which matters for resources that shouldn''t be recreated on every rebuild unless their actual dependency changed.', 'dart', 'MultiProvider(
  providers: [
    Provider<ApiClient>(create: (_) => ApiClient()),
    ProxyProvider<ApiClient, UserRepository>(
      update: (context, apiClient, previous) => UserRepository(apiClient),
    ),
  ],
  child: const MyApp(),
)', '["Reaching for ProxyProvider chains when Riverpod''s simpler ref.watch(otherProvider) would express the same dependency more directly.","Not disposing a previous resource when it''s replaced, if it holds something needing explicit cleanup."]', '[]', '["what-is-provider"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('9191af84-c823-4aca-bb19-de7a2d4a66d6', 'choosing-state-management-solution', 'How do you decide which state management solution to use in a new Flutter project?', 'State Management', '["architecture"]', 'Intermediate', 'For most new apps, Riverpod is a safe default — for very small apps, setState alone is often enough; choose BLoC specifically when your team values strict, explicit event-driven architecture; avoid picking based on trend alone.', 'There''s no universally correct choice — it depends on team size, app complexity, and existing familiarity more than technical superiority. setState is genuinely correct for simple, localized UI state. Provider is reasonable for small-to-medium apps. Riverpod is the modern successor to Provider with compile-time safety and easier testing, a solid default for most new apps. BLoC suits teams that want the discipline of explicit events and strict unidirectional flow, often paying off in larger codebases. GetX offers the least ceremony but couples state, DI, and navigation together in ways that can hurt testability at scale.

The strong interview answer isn''t ''X is best'' — it''s demonstrating you understand the tradeoffs and can justify a choice based on specific app/team constraints, not just familiarity or hype.', NULL, NULL, '["Answering with a single ''best'' option without acknowledging tradeoffs.","Choosing a solution for a new project based purely on what''s trending rather than actual team/app fit."]', '["Structure your answer around concrete tradeoffs (team size, testability, learning curve) rather than a flat ranking."]', '["riverpod-vs-provider","bloc-pattern-explained"]', '["flutter-state-management-provider-vs-riverpod-vs-bloc","riverpod-vs-bloc-2026"]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('a14071cb-0dfb-40e1-8a16-1f55e9583182', 'solid-principles-flutter', 'How do SOLID principles apply to Flutter development?', 'Architecture', '["architecture","solid"]', 'Advanced', 'SOLID principles apply the same way they do in any OOP codebase — widgets, repositories, and use cases are the concrete places you apply them: single-responsibility widgets, interfaces for repositories (dependency inversion), and small, focused classes over sprawling ones.', 'Single Responsibility: a widget that fetches data, manages state, AND renders complex UI is doing too much — split it into a state-management layer and a purely presentational widget. Open/Closed: branching on if (type == ''card'') else if (type == ''paypal'') violates this; a strategy pattern lets you add a new type without modifying existing code. Liskov Substitution: a subclass of a widget or repository should be usable anywhere the base type is expected without breaking behavior. Interface Segregation: a repository interface with 15 methods when a consumer only needs 2 forces unnecessary coupling. Dependency Inversion: the most visible in Flutter''s Clean Architecture — the domain layer defines a UserRepository abstract class, and the data layer implements it, so business logic doesn''t depend on low-level details.', NULL, NULL, '["Treating SOLID as Flutter-specific trivia rather than general OOP design principles that show up in Flutter''s architecture patterns.","Over-applying SOLID to a tiny app, adding abstractions for things that will realistically never have a second implementation."]', '[]', '["clean-architecture-flutter","dependency-injection-flutter"]', '["flutter-clean-architecture-2026"]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('e2a6d697-17cf-4ad3-926c-b86aae384537', 'mvvm-vs-clean-architecture', 'How does MVVM compare to Clean Architecture in Flutter?', 'Architecture', '["architecture","mvvm"]', 'Advanced', 'MVVM (Model-View-ViewModel) is primarily about separating presentation logic from UI; Clean Architecture is a broader, layered approach that MVVM can actually live inside as the presentation layer''s specific pattern.', 'MVVM''s core idea: the View (widget) is ''dumb'' and only renders whatever state the ViewModel exposes, forwarding user actions to it — in Flutter, a ChangeNotifier or Riverpod Notifier commonly plays the ViewModel role. This solves presentation-layer concerns specifically: keeping business logic out of widgets.

Clean Architecture is a superset concern: it also dictates how the domain layer (entities, use cases) and data layer relate to presentation, via the dependency rule. A Flutter app using Clean Architecture typically implements its presentation layer using an MVVM-style ViewModel — the two aren''t competitors; MVVM answers ''how does the UI talk to logic,'' Clean Architecture answers the larger ''how are all layers organized.''', NULL, NULL, '["Treating MVVM and Clean Architecture as mutually exclusive alternatives rather than complementary.","Assuming MVVM requires a specific package — it''s a pattern, implementable with ChangeNotifier, Riverpod, Bloc, or plain classes."]', '[]', '["clean-architecture-flutter"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('6bfda451-88bf-4f23-9233-155291240be7', 'feature-first-vs-layer-first-structure', 'Feature-first vs layer-first folder structure — which is better for a Flutter project?', 'Architecture', '["architecture"]', 'Intermediate', 'Layer-first (grouping by technical layer) works fine for small apps; feature-first (grouping by feature, each containing its own presentation/domain/data) scales much better as an app grows, since related code stays together.', 'A layer-first structure (lib/widgets/, lib/repositories/, lib/models/) means working on a single feature requires jumping between many top-level folders, and it gets harder to see what belongs together as the app grows.

A feature-first structure (lib/features/auth/{presentation,domain,data}, lib/features/profile/{...}) keeps everything related to one feature co-located, making it easier to understand, test, and even delete a feature cleanly. Most teams combine both: feature-first at the top level, with each feature internally following Clean Architecture''s layer separation.', NULL, NULL, '["Sticking with pure layer-first as an app grows past a handful of screens, making navigation and onboarding progressively harder.","Going fully feature-first without shared/core folders for genuinely cross-cutting code, causing duplication across features."]', '[]', '["clean-architecture-flutter"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('aab4ff67-646a-4098-9d23-b5cb9d90632c', 'use-case-pattern-flutter', 'What is a Use Case in Clean Architecture and is it always necessary?', 'Architecture', '["architecture"]', 'Intermediate', 'A Use Case represents a single, specific business action, sitting in the domain layer and orchestrating one or more repository calls; it''s most valuable when business logic is genuinely complex, and can be overkill for simple CRUD-style operations.', 'A Use Case class typically exposes a single public method (often just call(), letting you invoke it like await loginUseCase(email, password)), containing business rules that don''t belong in a widget or repository. It sits between presentation (which calls it) and data (repositories it calls), keeping business logic testable in complete isolation.

For an operation that''s genuinely just ''call a repository method and return the result'' with zero additional logic, wrapping it in a Use Case adds indirection without real benefit — some teams skip Use Cases for trivial passthrough operations.', 'dart', 'class LoginUseCase {
  final AuthRepository _repo;
  const LoginUseCase(this._repo);

  Future<Either<Failure, User>> call({required String email, required String password}) {
    if (email.isEmpty) return Future.value(Left(ValidationFailure(''Email required'')));
    return _repo.login(email: email, password: password);
  }
}', '["Mechanically creating a Use Case for every single repository method even when it adds zero logic.","Putting complex business logic directly in a Bloc/ViewModel instead of a Use Case when it warrants isolated unit testing."]', '[]', '["clean-architecture-flutter"]', '["flutter-clean-architecture-2026"]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('ac8e90c9-9a4f-4e7c-8983-0c45d8331165', 'dto-vs-entity-vs-model', 'What''s the difference between a DTO, a Model, and an Entity in Clean Architecture?', 'Architecture', '["architecture"]', 'Advanced', 'An Entity is a pure business object living in the domain layer with no knowledge of JSON or databases; a Model (or DTO) lives in the data layer, knows how to (de)serialize from a specific data source, and gets converted into an Entity before crossing into the domain layer.', 'Entities represent ''what the business cares about'' — a User entity might just have id, name, email, with no fromJson/toJson, since the domain layer shouldn''t know or care where data comes from. A Model lives in the data layer, mirrors the exact shape of an API response or database row, and knows how to serialize/deserialize that specific format.

The repository implementation converts a Model into an Entity (often via a toEntity() method) before returning it to domain/presentation layers — this is what lets you swap a REST API for GraphQL, or change a database schema, without rippling into business logic.', 'dart', '// Data layer
class UserModel {
  final String id, name, email;
  UserModel.fromJson(Map<String, dynamic> json)
      : id = json[''id''], name = json[''name''], email = json[''email''];

  UserEntity toEntity() => UserEntity(id: id, name: name, email: email);
}

// Domain layer — no JSON knowledge at all
class UserEntity {
  final String id, name, email;
  const UserEntity({required this.id, required this.name, required this.email});
}', '["Passing Models directly up into domain/presentation layers instead of converting to Entities first, leaking data-layer concerns upward.","Creating a separate Entity and identical Model for every project regardless of whether the API shape ever differs from the domain shape."]', '[]', '["clean-architecture-flutter","repository-pattern-flutter"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('3f318e38-1f84-41a0-a24a-b6c3c1cd8c59', 'flutter-devtools-profiling', 'How do you use Flutter DevTools to diagnose a performance problem?', 'Flutter Performance', '["performance","devtools"]', 'Intermediate', 'Run the app in profile mode (not debug), open the Performance/CPU Profiler view in DevTools, record a timeline while reproducing the janky interaction, and look for frames exceeding the 16ms (60fps) budget, then inspect which widget''s build/layout/paint is taking too long.', 'Debug mode includes extra assertions and disables optimizations, making its performance numbers unreliable — always profile in flutter run --profile, never debug mode. DevTools'' Performance view shows a frame-by-frame timeline; frames above the 16ms line (for 60fps) are janky. Clicking a slow frame shows a flame chart breaking down exactly which build/layout/paint calls consumed the time.

The ''Track Widget Builds'' and ''Track Layouts/Paints'' options add markers showing which widgets rebuilt during a slow frame — often revealing a widget rebuilding far more often than expected.', NULL, NULL, '["Profiling in debug mode and drawing performance conclusions from it — debug mode numbers don''t reflect real release performance.","Guessing at the cause of jank instead of actually recording a DevTools timeline."]', '["Explicitly say ''profile mode, not debug mode'' — this specific detail is a common interview differentiator."]', '["avoid-unnecessary-rebuilds"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('057f550f-e965-435d-aee1-421af798ea53', 'repaintboundary-usage', 'What does RepaintBoundary do and when should you use it?', 'Flutter Performance', '["performance"]', 'Advanced', 'RepaintBoundary isolates its child into a separate compositing layer, so repainting that subtree doesn''t force everything around it to repaint too — useful for expensive-to-paint widgets that change independently, but overusing it wastes memory on unnecessary layers.', 'Normally, when part of the widget tree needs to repaint, Flutter may need to repaint more of the tree around it. Wrapping an expensive or frequently-changing widget (like a complex CustomPainter animation) in RepaintBoundary gives it its own GPU-composited layer, isolating its repaints from siblings and ancestors — genuinely helpful when you have one ''hot'' widget in an otherwise static area of the screen.

The tradeoff is memory: each RepaintBoundary layer costs GPU memory to maintain, so wrapping everything speculatively actually hurts performance rather than helping.', NULL, NULL, '["Sprinkling RepaintBoundary throughout the tree speculatively without profiling first.","Not realizing Flutter already inserts implicit RepaintBoundaries in some cases — manually adding one may be redundant."]', '[]', '["const-widgets-flutter"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('834f21ad-fc62-4012-9d60-7f47e084c206', 'image-caching-precacheimage', 'How does Flutter cache images, and what does precacheImage do?', 'Flutter Performance', '["performance","images"]', 'Intermediate', 'Flutter''s ImageCache automatically caches decoded images in memory by default so repeated use of the same image doesn''t re-decode it; precacheImage() lets you proactively load and decode an image into that cache before it''s actually displayed, avoiding a visible pop-in.', 'Image.network/Image.asset use an ImageProvider that resolves through Flutter''s global ImageCache, keyed by the image''s configuration. Once decoded, subsequent uses of the same image are instant, up to the cache''s size limits, which you can tune for image-heavy apps.

precacheImage(imageProvider, context) triggers the decode-and-cache step ahead of time — commonly called during a splash/loading screen for images you know will be needed soon, so when the image actually needs to render, it appears instantly instead of showing a blank space while decoding.', 'dart', '@override
void didChangeDependencies() {
  super.didChangeDependencies();
  precacheImage(const AssetImage(''assets/next_screen_hero.png''), context);
}', '["Loading large, unresized images at full resolution — decoding at full resolution wastes memory even with caching; use cacheWidth/cacheHeight to decode at display size.","Not accounting for the ImageCache''s size limits when working with many large images, causing thrashing."]', '[]', '[]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('d9792dbe-b53c-4501-98d6-463de3f8df4d', 'flutter-build-modes-explained', 'What''s the difference between Flutter''s debug, profile, and release build modes?', 'Flutter Performance', '["performance","build"]', 'Beginner', 'Debug mode includes assertions, hot reload, and debugging info at the cost of performance; profile mode strips debug overhead but keeps enough tooling support to profile performance accurately; release mode is fully optimized and stripped for production.', 'Debug mode (flutter run) enables hot reload, assertions, and service extensions for DevTools, all adding overhead — debug-mode performance is not representative of what users experience.

Profile mode (flutter run --profile) disables most debug-only overhead while retaining just enough instrumentation for DevTools to profile timing accurately — the correct mode for any real performance measurement. Release mode is fully AOT-compiled and optimized with all debugging hooks stripped, matching exactly what end users get.', NULL, NULL, '["Drawing performance conclusions from debug-mode runs, since debug mode is deliberately much slower than what users experience.","Testing app size or startup time in debug mode instead of a release build."]', '[]', '["flutter-devtools-profiling"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('1fa410af-ccdd-4e85-9a29-d86be1765f1d', 'firebase-security-rules-basics', 'How do Firestore Security Rules work?', 'Firebase Integration', '["firebase","firestore","security"]', 'Intermediate', 'Security Rules are a separate, declarative configuration that Firestore evaluates server-side on every read/write request, deciding whether to allow it based on the requesting user''s auth state and the data being accessed — they''re your only real line of defense since client-side checks can be bypassed.', 'Rules are written in a rules-specific language and deployed separately from your app. A basic rule might be match /users/{userId} { allow read, write: if request.auth != null && request.auth.uid == userId; } — only the authenticated user matching the document''s ID can read/write their own document.

Because rules run entirely server-side, they''re the actual security boundary — any check done only in Flutter code can be bypassed by calling the Firestore API directly, so sensitive authorization logic must live in rules. Testing rules locally via the Firestore emulator before deploying is standard practice.', 'yaml', 'rules_version = ''2'';
service cloud.firestore {
  match /databases/{database}/documents {
    match /users/{userId} {
      allow read, write: if request.auth != null && request.auth.uid == userId;
    }
  }
}', '["Relying on client-side checks alone (e.g. only hiding a delete button) instead of enforcing the restriction in Security Rules.","Writing overly permissive rules during development and forgetting to tighten them before shipping."]', '["Emphasize that rules are the real security boundary, not client-side code."]', '["firestore-vs-realtime-database"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('9e7e0443-b4d7-44cb-b885-90bee1edb306', 'firebase-crashlytics-setup', 'How do you set up Firebase Crashlytics to catch Flutter errors?', 'Firebase Integration', '["firebase","crashlytics"]', 'Intermediate', 'Wire both FlutterError.onError (for framework/widget-build errors) and PlatformDispatcher.instance.onError (for uncaught async errors) to record errors to Crashlytics, since neither alone catches every category of error.', 'Flutter has two largely separate error channels: framework errors surface through FlutterError.onError, while errors in async code outside the framework''s direct control need PlatformDispatcher.instance.onError (or the older runZonedGuarded pattern). Missing either means a whole category of production crashes never reaches Crashlytics.

A complete setup overrides both in main(), before runApp().', 'dart', 'void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp();

  FlutterError.onError = FirebaseCrashlytics.instance.recordFlutterFatalError;

  PlatformDispatcher.instance.onError = (error, stack) {
    FirebaseCrashlytics.instance.recordError(error, stack, fatal: true);
    return true;
  };

  runApp(const MyApp());
}', '["Wiring only FlutterError.onError and assuming all crashes are covered — uncaught async errors need PlatformDispatcher.onError separately.","Testing Crashlytics setup only in debug mode — reporting typically needs a real/release-like build and can be delayed in delivery."]', '[]', '["dart-zones-explained"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');
INSERT OR IGNORE INTO "interview_questions" ("id", "slug", "question", "category", "tags", "difficulty", "short_answer", "explanation", "code_language", "code_example", "common_mistakes", "interview_tips", "related_slugs", "related_article_slugs", "related_tool_slugs", "status", "created_at", "updated_at") VALUES ('1fc891b9-0519-40c8-99ec-29a18c5eb965', 'firebase-remote-config-vs-ab-testing', 'How do Firebase Remote Config and A/B Testing work together?', 'Firebase Integration', '["firebase","remote-config"]', 'Advanced', 'Remote Config supplies the actual parameter values your app reads at runtime; Firebase A/B Testing sits on top of it, automatically assigning users to different Remote Config parameter variants and measuring which performs better against a chosen metric.', 'Used alone, Remote Config just lets you change values without a release. A/B Testing builds an experiment on top: you define two or more variants of a Remote Config parameter, Firebase randomly assigns each user to a variant, and tracks a target metric tied to Analytics events, computing statistical significance automatically.

The practical setup: your app code only ever reads the Remote Config parameter normally — it has no awareness an experiment is running. Variant assignment and analysis happen entirely on Firebase''s side, keeping app code identical regardless of whether a parameter is under active experimentation.', NULL, NULL, '["Writing experiment-aware branching logic in the app instead of just reading the Remote Config value normally.","Not setting Remote Config default values, so users see an undefined/fallback state before the first successful fetch."]', '[]', '["firebase-remote-config"]', '[]', '[]', 'published', '2026-08-28T17:11:25.29317+00:00', '2026-08-28T17:11:25.29317+00:00');